INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('database-pooling', 'Connection Pooling: PgBouncer & Pool Aplikasi', 'Buka-tutup koneksi database itu mahal: pakai pool agar ribuan request berbagi sedikit koneksi', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80', 'Ruang server', 'Database', 'Menengah', '["database","pooling","pgbouncer","koneksi"]', 'Deni', '2026-11-13', '2026-11-13', 'database-query', 1, '["database-query","nginx-load-balancing","linux-tuning"]', 'PgBouncer Documentation', 'https://www.pgbouncer.org/', '[{"level":2,"text":"Koneksi Baru Itu Mahal","type":"heading"},{"text":"Membuka koneksi database baru terdengar sepele, tetapi di balik layar ada proses yang cukup berat: **handshake TCP**, autentikasi pengguna, alokasi memori untuk session, dan seringkali negosiasi **TLS**. Pada koneksi lokal, seluruh proses ini memakan waktu 1 sampai 5 milidetik, dan pada koneksi lintas data center atau cloud bisa mencapai 10 sampai 50 milidetik. Kedengarannya kecil, sampai kamu sadar bahwa aplikasi web modern membuka koneksi baru untuk setiap request yang masuk. Dengan 1.000 request per detik, itu berarti 1.000 handshake per detik, dan CPU database habis hanya untuk membuka dan menutup koneksi, bukan untuk menjalankan query. Lebih parah lagi, setiap koneksi yang terbuka memakan memori di server database, sekitar 2 sampai 10 MB per koneksi di PostgreSQL, sehingga 1.000 koneksi bersamaan bisa menghabiskan 10 GB RAM hanya untuk menahan koneksi yang sebagian besar sedang menganggur menunggu query berikutnya.","type":"paragraph"},{"text":"Inilah masalah yang dipecahkan oleh **connection pooling**: daripada membuka koneksi baru untuk setiap request, aplikasi memakai sekelompok kecil koneksi yang sudah terbuka dan dipakai bergantian. Request yang selesai mengembalikan koneksinya ke pool, lalu request berikutnya memakai koneksi yang sama. Hasilnya dramatis: latency per request turun karena tidak ada lagi handshake, CPU database terbebas dari pekerjaan pembukaan koneksi, dan jumlah koneksi ke database menjadi terkendali dan bisa diprediksi. Pooling bukan optimasi kecil, melainkan fondasi yang wajib ada di setiap aplikasi yang melayani ratusan request bersamaan.","type":"paragraph"},{"kind":"info","text":"PostgreSQL memakai satu proses per koneksi, jadi 1.000 koneksi berarti 1.000 proses yang berebut CPU dan RAM. MySQL lebih ringan per koneksi (thread, bukan proses), tetapi tetap punya batas max_connections dan biaya memori per thread.","title":"Kenapa PostgreSQL paling rentan","type":"callout"},{"level":2,"text":"PgBouncer: Pool di Sisi Server","type":"heading"},{"text":"**PgBouncer** adalah connection pooler ringan yang duduk di antara aplikasi dan PostgreSQL. Aplikasi terhubung ke PgBouncer seperti terhubung ke database biasa, dan PgBouncer yang mengatur berapa koneksi nyata yang dibuka ke PostgreSQL. Keunggulannya adalah aplikasi tidak perlu diubah sama sekali: cukup arahkan string koneksi ke port PgBouncer (biasanya 6432), dan semua pooling terjadi secara transparan. PgBouncer sangat ringan, satu prosesnya sanggup menangani puluhan ribu koneksi klien dengan hanya puluhan koneksi nyata ke database.","type":"paragraph"},{"text":"PgBouncer punya tiga mode operasi yang harus dipilih dengan hati-hati. Mode **session** memberikan satu koneksi database untuk satu koneksi klien selama klien itu terhubung, paling aman tetapi paling boros. Mode **transaction** memberikan koneksi database hanya selama satu transaksi berjalan, lalu langsung mengembalikannya ke pool saat transaksi selesai, sehingga ratusan klien bisa berbagi puluhan koneksi; ini mode yang paling umum dipakai dan paling efisien. Mode **statement** lebih ekstrem lagi, koneksi dikembalikan setiap satu statement, tetapi mode ini merusak fitur yang membutuhkan session, seperti prepared statement dan advisory lock, jadi hanya dipakai untuk kasus khusus. Untuk hampir semua aplikasi web, mode transaction adalah jawaban yang benar.","type":"paragraph"},{"code":"; Konfigurasi PgBouncer minimal untuk production\n[databases]\nmyapp = host=127.0.0.1 port=5432 dbname=myapp\n\n[pgbouncer]\nlisten_addr = 127.0.0.1\nlisten_port = 6432\npool_mode = transaction\n; Jumlah koneksi nyata ke PostgreSQL\ndefault_pool_size = 25\n; Jumlah klien yang boleh mengantre/terhubung\nmax_client_conn = 1000\n; Koneksi yang menganggur lebih dari 60 detik ditutup\nserver_idle_timeout = 60\n; Akun admin untuk perintah SHOW POOLS\nadmin_users = postgres","filename":"pgbouncer.ini","language":"bash","type":"code"},{"level":2,"text":"Berapa Besar Pool yang Ideal?","type":"heading"},{"text":"Kesalahan paling umum adalah membuat pool terlalu besar. Logikanya terasa benar, lebih banyak koneksi berarti lebih banyak query yang bisa jalan bersamaan, tetapi kenyataannya sebaliknya: di atas jumlah tertentu, koneksi tambahan justru membuat semuanya lebih lambat karena CPU database sibuk berpindah-pindah antar koneksi (**context switching**) dan lock antar transaksi semakin sering bertabrakan. Ada rumus praktis yang dipakai luas di industri, dipopulerkan oleh HikariCP: **connections = ((core_count * 2) + effective_spindle_count)**. Untuk server database 4 core dengan disk SSD (effective spindle count 1), ukuran pool ideal adalah (4 * 2) + 1 = **9 koneksi**. Angka ini memang terlihat kecil dan mengejutkan, tetapi sudah terbukti berulang kali: pool kecil yang sibuk hampir selalu mengalahkan pool besar yang saling berebut.","type":"paragraph"},{"code":"# Rumus ukuran pool (HikariCP):\n# connections = ((core_count * 2) + effective_spindle_count)\n#\n# Contoh server database 4 core + SSD:\n#   connections = (4 * 2) + 1 = 9\n# Contoh server database 8 core + SSD:\n#   connections = (8 * 2) + 1 = 17\n#\n# Aturan praktis: mulai dari angka rumus, lalu naikkan sedikit demi\n# sedikit sambil memantau antrean. Pool yang sehat hampir penuh tapi\n# tidak pernah membuat request menunggu lebih dari 50-100 ms.","filename":"pool-size.txt","language":"plaintext","type":"code"},{"kind":"tip","text":"Jangan menebak ukuran pool dari jumlah pengguna. Yang penting adalah berapa query yang benar-benar berjalan bersamaan, dan itu ditentukan oleh core CPU database, bukan oleh jumlah pengunjung situs kamu.","title":"Pool dihitung dari CPU, bukan dari pengguna","type":"callout"},{"level":2,"text":"Pool di Sisi Aplikasi","type":"heading"},{"text":"Selain PgBouncer, setiap aplikasi modern punya pool bawaannya sendiri. Di dunia Java ada **HikariCP**, di Node.js ada **pg Pool** dan **mysql2 pool**, di Python ada **SQLAlchemy pool**, di Go ada **database/sql** dengan `SetMaxOpenConns`. Pool aplikasi dan PgBouncer bisa dipakai bersamaan: pool aplikasi membatasi koneksi per instance aplikasi, sedangkan PgBouncer membatasi total koneksi ke database dari semua instance. Kuncinya adalah menghitung totalnya dengan benar: kalau kamu punya 5 instance aplikasi dan masing-masing punya pool 20 koneksi, totalnya 100 koneksi ke database, jadi pastikan PostgreSQL sanggup menanganinya (cek `max_connections`) atau pasang PgBouncer di tengah dengan `default_pool_size` 25.","type":"paragraph"},{"code":"// Pool di aplikasi Node.js (library pg)\nimport { Pool } from ''pg'';\n\nconst pool = new Pool({\n  host: ''127.0.0.1'',\n  port: 6432,          // lewat PgBouncer, bukan langsung ke PostgreSQL\n  database: ''myapp'',\n  user: ''app'',\n  password: process.env.DB_PASSWORD,\n  max: 10,             // koneksi per instance aplikasi\n  idleTimeoutMillis: 30000,  // tutup koneksi menganggur setelah 30 detik\n  connectionTimeoutMillis: 2000, // gagal cepat kalau pool penuh\n});\n\nconst result = await pool.query(''SELECT * FROM products WHERE id = $1'', [42]);","filename":"pool.js","language":"plaintext","type":"code"},{"type":"code","language":"yaml","filename":"application.yml","code":"# Pool di aplikasi Spring Boot (HikariCP, pool default Spring)\nspring:\n  datasource:\n    url: jdbc:postgresql://127.0.0.1:6432/myapp  # lewat PgBouncer\n    username: app\n    password: ${DB_PASSWORD}\n    hikari:\n      maximum-pool-size: 10      # koneksi per instance aplikasi\n      minimum-idle: 2\n      idle-timeout: 30000        # 30 detik\n      connection-timeout: 2000   # gagal cepat kalau pool penuh\n      max-lifetime: 1800000      # 30 menit, hindari koneksi basi"},{"level":2,"text":"Antrean Saat Pool Penuh","type":"heading"},{"text":"Saat semua koneksi di pool sedang dipakai, request berikutnya harus **mengantre** menunggu koneksi kosong. Antrean yang pendek dan cepat adalah hal normal, tetapi antrean yang panjang adalah sinyal bahaya. Ada dua hal yang harus diatur: pertama, **connectionTimeoutMillis**, yaitu berapa lama request boleh menunggu sebelum dinyatakan gagal; nilai 2 sampai 5 detik adalah wajar, dan gagal cepat jauh lebih baik daripada menunggu 30 detik lalu timeout di sisi pengguna. Kedua, pantau metrik antrean secara rutin: kalau antrean sering terisi, itu bukan berarti pool harus diperbesar, melainkan biasanya ada query lambat yang menahan koneksi terlalu lama. Perbaiki query-nya dulu, baru pertimbangkan menambah pool, dan kalau memang harus menambah, tambahkan sedikit demi sedikit sambil mengukur dampaknya.","type":"paragraph"},{"headers":["Skenario","Tanpa pool","Dengan pool (9 koneksi)"],"rows":[["1.000 req/detik, query 5 ms","1.000 handshake/detik, CPU database 90%","9 koneksi dipakai bergantian, CPU 15%"],["Lonjakan 5.000 koneksi bersamaan","Database menolak koneksi, error berantai","PgBouncer mengantrekan 5.000 klien ke 25 koneksi"],["Latency rata-rata request","15-50 ms (termasuk handshake)","2-6 ms (tanpa handshake)"]],"type":"table"},{"kind":"warning","text":"Jangan menaikkan max_connections PostgreSQL ke ribuan untuk mengatasi error too many connections. Itu hanya memindahkan masalah: CPU dan RAM database akan habis untuk menahan proses koneksi. Pasang pooler seperti PgBouncer, dan biarkan max_connections tetap di kisaran 100 sampai 300.","title":"Jangan sembarangan menaikkan max_connections","type":"callout"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi dan panduan lanjutan tersedia di [PgBouncer Documentation](https://www.pgbouncer.org/) dan [PostgreSQL Connection Settings](https://www.postgresql.org/docs/current/runtime-config-connection.html).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('database-query', 'Optimasi Query: Index, EXPLAIN & Slow Query Log', 'Query lambat adalah pembunuh performa nomor satu: temukan dengan EXPLAIN dan perbaiki dengan index', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80', 'Grafik analitik', 'Database', 'Menengah', '["database","query","index","mysql","postgresql"]', 'Deni', '2026-11-13', '2026-11-13', NULL, 1, '["database-pooling","redis-cache","linux-tuning"]', 'MySQL Optimization', 'https://dev.mysql.com/doc/refman/8.0/en/optimization.html', '[{"level":2,"text":"Query Lambat Membunuh dari Dalam","type":"heading"},{"text":"Kebanyakan aplikasi tidak mati karena traffic-nya terlalu besar, melainkan karena query-nya terlalu lambat. Satu query yang memakan waktu 2 detik dan dijalankan 50 kali per detik akan menahan 100 koneksi database sekaligus, dan begitu koneksi habis, semua request lain ikut mengantre, lalu timeout berantai. Inilah yang membuat optimasi query menjadi pekerjaan performa nomor satu di sisi database: memperbaiki satu query yang lambat sering kali berdampak lebih besar daripada menambah RAM atau CPU server. Kabar baiknya, database modern memberi kita alat yang sangat jelas untuk menemukan dan memperbaiki query bermasalah: **EXPLAIN** untuk melihat rencana eksekusi, **index** untuk mempercepat pencarian, dan **slow query log** untuk menangkap query yang diam-diam menghabiskan waktu.","type":"paragraph"},{"text":"Sebelum menyentuh satu baris SQL pun, pahami dulu satu angka kunci: berapa baris yang harus dibaca database untuk menjawab query kamu. Query yang bagus membaca ratusan baris, query yang buruk membaca jutaan baris untuk mengembalikan sepuluh. Semua teknik dalam artikel ini bermuara ke satu tujuan itu: buat database membaca sesedikit mungkin, dan buat ia menemukan baris yang dicari tanpa memindai seluruh tabel.","type":"paragraph"},{"level":2,"text":"Membaca EXPLAIN Seperti Profesional","type":"heading"},{"text":"Perintah **EXPLAIN** meminta database menunjukkan rencananya sebelum menjalankan query. Di MySQL dan PostgreSQL, outputnya berisi beberapa kolom kunci yang wajib kamu baca. Kolom **type** menunjukkan cara database mengakses tabel: `const` dan `eq_ref` berarti pencarian langsung lewat primary key dan itu ideal, `ref` dan `range` berarti pencarian lewat index dan itu bagus, sedangkan `ALL` berarti **full table scan**, alias database membaca seluruh tabel dari baris pertama sampai terakhir. Kalau kamu melihat `ALL` pada tabel dengan jutaan baris, di situlah masalahnya. Kolom **key** menunjukkan index yang dipakai, dan kalau isinya **NULL**, berarti tidak ada index yang dipakai sama sekali. Kolom **rows** adalah perkiraan jumlah baris yang harus diperiksa, dan kolom **Extra** memberi petunjuk tambahan: `Using filesort` berarti database harus mengurutkan sendiri di memori atau disk, dan `Using temporary` berarti ia membuat tabel sementara, keduanya mahal untuk query yang sering dijalankan.","type":"paragraph"},{"code":"-- Jalankan EXPLAIN sebelum query apa pun yang mencurigakan\nEXPLAIN SELECT id, name, price\nFROM products\nWHERE category_id = 4 AND status = ''active''\nORDER BY created_at DESC\nLIMIT 20;\n\n-- Contoh hasil yang SEHAT:\n-- type: ref | key: idx_category_status | rows: 120 | Extra: Using index condition\n-- Contoh hasil yang BERMASALAH:\n-- type: ALL | key: NULL | rows: 2.400.000 | Extra: Using filesort","filename":"explain.sql","language":"sql","type":"code"},{"kind":"tip","text":"Biasakan menjalankan EXPLAIN untuk setiap query baru sebelum masuk ke production. Query yang terlihat sederhana di development dengan 100 baris data bisa berubah menjadi bencana di production dengan 10 juta baris data.","title":"EXPLAIN dulu, deploy kemudian","type":"callout"},{"level":2,"text":"Index B-Tree dan Composite Index","type":"heading"},{"text":"**Index** adalah struktur data tambahan, biasanya **B-tree**, yang memungkinkan database menemukan baris tanpa memindai seluruh tabel. Analogi paling sederhananya adalah indeks di akhir buku: tanpa indeks kamu harus membaca halaman demi halaman, dengan indeks kamu langsung melompat ke halaman yang dicari. Index memang mempercepat baca, tetapi ada harganya: setiap index membuat operasi tulis (INSERT, UPDATE, DELETE) sedikit lebih lambat karena index juga harus diperbarui, dan setiap index memakan ruang disk. Karena itu jangan membuat index untuk semua kolom secara membabi buta; buatlah index untuk kolom yang dipakai di klausa WHERE, JOIN, dan ORDER BY pada query yang paling sering dijalankan.","type":"paragraph"},{"text":"Untuk query dengan lebih dari satu kondisi, **composite index** (index gabungan atas beberapa kolom) hampir selalu lebih baik daripada beberapa index kolom tunggal. Urutan kolom di dalam composite index sangat penting dan mengikuti aturan **leftmost prefix**: database hanya bisa memakai index dari kolom paling kiri secara berurutan. Untuk query `WHERE category_id = 4 AND status = ''active'' ORDER BY created_at DESC`, index `(category_id, status, created_at)` adalah pilihan ideal, karena ketiga kondisi terpenuhi dalam satu index dan pengurutan pun sudah berurutan di dalam index itu sendiri, sehingga `filesort` hilang. Sebaliknya, index `(status, category_id, created_at)` jauh kurang efektif untuk query yang sama, karena kolom `status` yang punya sedikit nilai berbeda (kardinalitas rendah) diletakkan di depan dan hampir tidak menyaring apa-apa.","type":"paragraph"},{"code":"-- Index gabungan: urutan kolom = urutan kondisi di WHERE, lalu ORDER BY\nCREATE INDEX idx_products_cat_status_created\n  ON products (category_id, status, created_at DESC);\n\n-- Cek index apa saja yang sudah ada di sebuah tabel (MySQL)\nSHOW INDEX FROM products;\n\n-- Cek ukuran index (PostgreSQL)\nSELECT indexrelname, pg_size_pretty(pg_relation_size(indexrelid))\nFROM pg_stat_user_indexes\nWHERE relname = ''products'';","filename":"index.sql","language":"sql","type":"code"},{"kind":"warning","text":"Index yang terlalu banyak justru memperlambat aplikasi yang banyak menulis. Tabel dengan 10 index bisa membuat satu INSERT menjadi 5 sampai 10 kali lebih lambat. Hapus index yang tidak pernah dipakai — cek dengan pg_stat_user_indexes di PostgreSQL atau performance_schema di MySQL.","title":"Index bukan gratis","type":"callout"},{"level":2,"text":"Slow Query Log: Tangkap Pelakunya","type":"heading"},{"text":"Menebak-nebak query mana yang lambat adalah buang-buang waktu. Nyalakan **slow query log** dan biarkan database sendiri yang melaporkan pelakunya. Di MySQL, atur `long_query_time` ke 1 detik (atau 0,5 detik di server sibuk) dan semua query yang lebih lambat dari itu akan tercatat lengkap dengan waktu eksekusinya. Di PostgreSQL, padanannya adalah `log_min_duration_statement`. Setelah satu hari berjalan di production, urutkan log berdasarkan total waktu (bukan sekali jalan): query yang hanya 0,5 detik tetapi dijalankan 100.000 kali sehari jauh lebih merugikan daripada query 5 detik yang hanya jalan sekali semalam.","type":"paragraph"},{"code":"# MySQL: aktifkan slow query log, tangkap query di atas 1 detik\n[mysqld]\nslow_query_log = 1\nslow_query_log_file = /var/log/mysql/slow.log\nlong_query_time = 1\nlog_queries_not_using_indexes = 1\n\n# Analisis log: 10 query dengan total waktu tertinggi\n# mysqldumpslow -s t /var/log/mysql/slow.log | head -20\n\n# PostgreSQL: catat query di atas 500 ms\n# log_min_duration_statement = 500  # di postgresql.conf","filename":"slow-query.cnf","language":"bash","type":"code"},{"level":2,"text":"N+1 Query: Perangkap Paling Umum","type":"heading"},{"text":"Pola paling umum yang membunuh performa aplikasi adalah **N+1 query**: satu query untuk mengambil daftar (misalnya 50 produk), lalu satu query tambahan untuk setiap item di daftar itu (misalnya harga atau nama kategori tiap produk). Totalnya menjadi 51 query untuk satu halaman. Solusinya adalah mengambil data terkait sekaligus dengan **JOIN** atau **IN (...)**, atau memakai eager loading di ORM (misalnya `with()` di Laravel atau `select_related` di Django). Satu query yang mengembalikan 50 baris hampir selalu lebih cepat daripada 50 query yang masing-masing mengembalikan 1 baris, karena setiap query punya biaya tetap: parsing, perencanaan, dan round trip jaringan.","type":"paragraph"},{"code":"-- BURUK: N+1 query (1 + 50 query untuk satu halaman)\n-- SELECT * FROM products LIMIT 50;\n-- lalu untuk tiap produk: SELECT name FROM categories WHERE id = ?;\n\n-- BAIK: satu query dengan JOIN, semua data kembali sekaligus\nSELECT p.id, p.name, p.price, c.name AS category_name\nFROM products p\nJOIN categories c ON c.id = p.category_id\nWHERE p.status = ''active''\nORDER BY p.created_at DESC\nLIMIT 50;","filename":"n-plus-one.sql","language":"sql","type":"code"},{"level":2,"text":"SELECT * vs Kolom Spesifik","type":"heading"},{"text":"Kebiasaan menulis **SELECT \\*** terlihat sepele, tetapi dampaknya nyata. Database harus membaca semua kolom, termasuk kolom besar seperti deskripsi panjang atau blob, lalu mengirim semuanya melalui jaringan ke aplikasi, padahal halaman mungkin hanya butuh tiga kolom. Menyebut kolom secara spesifik juga memungkinkan database memakai **covering index**: kalau semua kolom yang diminta sudah ada di dalam index, database tidak perlu menyentuh tabel sama sekali dan menjawab langsung dari index. Pada tabel dengan puluhan kolom, mengganti `SELECT *` dengan tiga kolom spesifik bisa memangkas waktu query 30 sampai 70 persen, terutama kalau ada kolom teks besar di tabel itu.","type":"paragraph"},{"headers":["Perubahan","Sebelum","Sesudah"],"rows":[["Tambah composite index","Full scan 2,4 juta baris, 1.800 ms","Index range 120 baris, 3 ms"],["Hilangkan N+1 query","51 query, 420 ms per halaman","1 query, 18 ms per halaman"],["SELECT * jadi 3 kolom","Mengirim 1,2 MB per halaman","Mengirim 90 KB per halaman"],["Slow query log 1 detik","Tidak tahu query mana yang lambat","10 query teratas terpantau harian"]],"type":"table"},{"kind":"info","text":"Angka di tabel adalah contoh dari kasus nyata yang umum, bukan janji. Selalu ukur sebelum dan sesudah perubahan dengan EXPLAIN dan slow query log di database kamu sendiri.","title":"Ukur, jangan menebak","type":"callout"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi dan panduan lanjutan tersedia di [MySQL Optimization](https://dev.mysql.com/doc/refman/8.0/en/optimization.html) dan [PostgreSQL Query Planning](https://www.postgresql.org/docs/current/performance-tips.html).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('file-download', 'Download File Cepat: sendfile & X-Accel-Redirect', 'Kirim file besar tanpa membebani aplikasi: serahkan ke kernel dan NGINX', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80', 'Grafik analitik', 'Download & Cache', 'Menengah', '["nginx","download","sendfile","x-accel-redirect"]', 'Deni', '2026-11-13', '2026-11-13', NULL, 1, '["nginx-cache","nginx-compression","redis-cache"]', 'NGINX X-Accel', 'https://nginx.org/en/docs/http/ngx_http_proxy_module.html', '[{"text":"Mengirim file lewat aplikasi — mis. `readfile()` di PHP, `res.sendFile()` di Node, atau `FileResponse` di Python — terlihat sederhana, tapi mahal. Setiap download menahan satu worker aplikasi selama file terkirim, memakai memory untuk buffer, dan membebani CPU untuk menyalin data. Di 100 download bersamaan, 100 worker aplikasi sibuk hanya untuk mengirim byte. Solusinya: **serahkan pengiriman file ke NGINX dan kernel**. Dengan `sendfile` dan `X-Accel-Redirect`, aplikasi hanya memutuskan *apakah* pengguna boleh download — NGINX yang mengirim file-nya, dengan kecepatan mendekati kecepatan network dan hampir tanpa CPU.","type":"paragraph"},{"kind":"info","text":"`sendfile()` adalah system call Linux yang menyalin data langsung dari file di disk ke socket network — **tanpa melewati user-space sama sekali** (zero-copy). Tanpa sendfile, data menempuh 4 langkah: disk → kernel buffer → aplikasi → kernel socket → network. Dengan sendfile, tinggal 2 langkah: disk → kernel → network. Hasilnya: CPU untuk serving file statis turun **50–80%** dan throughput naik mendekati kecepatan kartu network.","title":"Zero-copy: kenapa sendfile begitu cepat","type":"callout"},{"level":2,"text":"sendfile on dan Teman-Temannya","type":"heading"},{"text":"Tiga directive ini adalah fondasi serving file statis di NGINX dan sebaiknya selalu aktif. `sendfile on` mengaktifkan zero-copy. `tcp_nopush on` membuat NGINX mengirim header HTTP dan potongan pertama file dalam satu paket TCP — mengurangi jumlah paket dan latency time-to-first-byte sekitar **5–10 ms**. `tcp_nodelay on` mematikan algoritma Nagle supaya paket kecil tidak ditahan menunggu ACK — penting untuk API dan file kecil. Untuk file besar, tambahkan `sendfile_max_chunk 512k` supaya satu koneksi download tidak memonopoli worker terlalu lama dalam satu putaran event loop.","type":"paragraph"},{"code":"# /etc/nginx/nginx.conf — blok http\nhttp {\n    sendfile            on;   # zero-copy: disk -> socket tanpa user-space\n    sendfile_max_chunk  512k; # kirim maks 512 KB per putaran event loop\n    tcp_nopush          on;   # header + isi pertama dalam satu paket\n    tcp_nodelay         on;   # jangan tunda paket kecil\n    output_buffers      1 128k; # buffer output sebelum tulis ke socket\n\n    # Jangan biarkan file besar mengusir file panas dari page cache\n    directio            4m;   # file > 4 MB dibaca bypass page cache\n    directio_alignment  512;\n}","filename":"/etc/nginx/nginx.conf (http)","language":"nginx","type":"code"},{"text":"Directive `directio 4m` sering terlewat padahal penting di server download. Secara default Linux menyimpan file yang dibaca ke page cache — bagus untuk file yang sering diakses, tapi buruk untuk file besar yang hanya di-download sekali. Satu file installer 2 GB bisa mengusir seluruh page cache (termasuk file aplikasi yang panas), sehingga request berikutnya harus baca dari disk yang lambat. Dengan `directio 4m`, file di atas 4 MB dibaca langsung dari disk tanpa mengotori cache, dan file kecil yang populer tetap ter-cache dengan baik.","type":"paragraph"},{"level":2,"text":"aio threads untuk File Besar dan Disk Lambat","type":"heading"},{"text":"`sendfile` cepat, tapi ia masih membaca dari disk secara synchronous: saat disk sibuk, worker NGINX ikut menunggu. Untuk file besar di disk lambat (HDD atau network storage), aktifkan **asynchronous I/O** dengan `aio threads`. Dengan ini, operasi baca disk dilempar ke thread pool, worker tetap bebas melayani request lain, dan throughput download dari disk lambat bisa naik **2–3 kali lipat**.","type":"paragraph"},{"code":"# /etc/nginx/nginx.conf — blok http\nhttp {\n    thread_pool download_pool threads=16 max_queue=65536;\n\n    server {\n        listen 443 ssl;\n        server_name files.contoh.id;\n\n        location /besar/ {\n            alias /var/www/files/;\n            aio threads=download_pool;  # baca disk async, worker tidak blokir\n            directio 4m;\n            output_buffers 1 512k;\n        }\n    }\n}","filename":"/etc/nginx/nginx.conf (http)","language":"nginx","type":"code"},{"kind":"tip","text":"`aio threads` paling terasa di dua kondisi: file besar (di atas 100 MB) dan storage lambat (HDD, NFS, atau disk cloud dengan IOPS terbatas). Di SSD NVMe yang cepat, perbedaannya kecil — tapi tidak ada ruginya mengaktifkannya untuk location download.","title":"Kapan aio threads terasa","type":"callout"},{"level":2,"text":"X-Accel-Redirect: Aplikasi Cek Izin, NGINX Kirim File","type":"heading"},{"text":"Bagaimana kalau file-nya tidak boleh diakses sembarang orang — mis. invoice, video berbayar, atau dokumen internal? Pola klasiknya: aplikasi mengecek izin (login, langganan, kuota), lalu **bukan** mengirim file sendiri, melainkan mengembalikan header khusus `X-Accel-Redirect` yang berisi path internal. NGINX menangkap header itu dan mengirim file dari disk dengan kecepatan penuh. Aplikasi bebas dalam milidetik, dan file tetap terlindungi karena path internal tidak bisa diakses langsung dari luar.","type":"paragraph"},{"code":"# 1. Aplikasi (Node.js/Express) — hanya cek izin, lalu lempar ke NGINX\napp.get(''/download/:id'', async (req, res) => {\n  const file = await db.files.findById(req.params.id);\n  if (!file || file.ownerId !== req.user.id) {\n    return res.status(403).send(''Tidak ada akses'');\n  }\n  // Jangan kirim file di sini — beri tahu NGINX saja:\n  res.set(''Content-Type'', file.mimeType);\n  res.set(''Content-Disposition'', `attachment; filename=\"${file.name}\"`);\n  res.set(''X-Accel-Redirect'', `/protected/${file.storedName}`);\n  res.status(200).end();\n});","filename":"app.js (Express)","language":"plaintext","type":"code"},{"code":"# 2. NGINX — location internal yang hanya bisa diakses via X-Accel-Redirect\nserver {\n    listen 443 ssl;\n    server_name files.contoh.id;\n\n    location /protected/ {\n        internal;  # TIDAK bisa diakses langsung dari browser!\n        alias /var/www/private-files/;\n        sendfile on;\n        tcp_nopush on;\n    }\n}\n\n# Uji: akses langsung harus 404\n# curl -I https://files.contoh.id/protected/rahasia.pdf  -> 404 Not Found\n# curl -I https://files.contoh.id/download/123 (dengan login) -> 200 + file","filename":"/etc/nginx/conf.d/files.conf","language":"nginx","type":"code"},{"text":"Directive `internal` adalah kuncinya: location itu **tidak bisa** dibuka langsung lewat URL, hanya lewat `X-Accel-Redirect` dari aplikasi. Pola yang sama ada di Apache (`X-Sendfile`) dan di framework modern biasanya disebut *sendfile* atau *accel redirect*. Keuntungannya berlapis: aplikasi tidak memegang koneksi download (worker bebas dalam <10 ms), file dikirim dengan zero-copy, dan aturan otorisasi tetap di satu tempat — di aplikasi, bukan tersebar di konfigurasi NGINX.","type":"paragraph"},{"level":2,"text":"Resume Download: Range Request","type":"heading"},{"text":"Download besar (video, installer, backup) pasti ada yang terputus di tengah jalan — jaringan seluler drop, laptop sleep, atau pengguna menekan pause. Tanpa dukungan **range request**, download harus diulang dari nol. Kabar baiknya: NGINX mendukung `Range` secara bawaan dan mengembalikan `206 Partial Content` dengan potongan file yang diminta. Download manager dan browser modern otomatis memanfaatkan ini untuk resume. Yang perlu kamu pastikan: jangan matikan fitur ini dengan `max_ranges 0`, dan pastikan `Content-Disposition` memakai `attachment` supaya browser mengunduh, bukan mencoba menampilkan file di tab.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/files.conf\nlocation /download/ {\n    alias /var/www/files/;\n    sendfile on;\n\n    # Range request AKTIF secara default — jangan dimatikan:\n    max_ranges 0;  # 0 = tanpa batas jumlah range per request (default)\n\n    # Paksa browser mengunduh, bukan menampilkan di tab\n    add_header Content-Disposition ''attachment'';\n\n    # Cache header: file statis boleh di-cache browser 7 hari\n    expires 7d;\n    add_header Cache-Control \"public, immutable\";\n}\n\n# Uji resume download dengan curl:\n# curl -r 0-999 https://files.contoh.id/download/app.zip -o part1\n# curl -r 1000- https://files.contoh.id/download/app.zip -o part2\n# cat part1 part2 > app.zip   # file lengkap kembali","filename":"/etc/nginx/conf.d/files.conf","language":"bash","type":"code"},{"kind":"warning","text":"Hati-hati dengan `expires` dan `Cache-Control: immutable` untuk file yang **namanya tidak berubah** tapi isinya bisa berubah (mis. `laporan-terbaru.pdf`). Browser akan memakai versi cache selama 7 hari dan pengguna tidak mendapat file baru. Solusi: beri nama file berversi (`laporan-2026-11-13.pdf`) atau fingerprint hash (`app.a1b2c3.zip`) — file yang tidak berubah boleh di-cache selamanya, file yang berubah harus punya nama baru.","title":"Jangan cache file yang isinya berubah","type":"callout"},{"level":2,"text":"Benchmark: Aplikasi vs NGINX","type":"heading"},{"text":"Seberapa besar perbedaannya? Di server 4 core dengan file 100 MB dan 50 download bersamaan, pola lama (aplikasi mengirim file) biasanya mentok di **150–250 MB/detik** dengan CPU 90% — worker aplikasi sibuk menyalin buffer. Dengan `sendfile` + `X-Accel-Redirect`, server yang sama mencapai **800–950 MB/detik** (mendekati kecepatan network 1 Gbps) dengan CPU di bawah 30%. Artinya satu server bisa melayani **4–5 kali lebih banyak** download bersamaan, dan aplikasi tetap responsif untuk request biasa karena worker-nya tidak tersandera download.","type":"paragraph"},{"headers":["Pola","Throughput (50 download)","CPU","Worker aplikasi"],"rows":[["Aplikasi kirim file (`readfile`/`sendFile`)","150–250 MB/detik","85–95%","Tersandera selama download"],["`sendfile` langsung dari NGINX","800–950 MB/detik","20–30%","Tidak terlibat"],["`X-Accel-Redirect` (file privat)","800–950 MB/detik","20–30%","Bebas dalam <10 ms"]],"type":"table"},{"items":["Aktifkan `sendfile on`, `tcp_nopush on`, dan `tcp_nodelay on` untuk semua file statis.","Pakai `directio 4m` supaya file besar tidak mengusir page cache.","Untuk file privat: aplikasi cek izin, lalu `X-Accel-Redirect` ke location `internal`.","Biarkan range request aktif supaya download bisa di-resume.","Beri nama file berversi sebelum memakai `Cache-Control: immutable`."],"ordered":true,"type":"list"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi yang dipakai di artikel ini: [NGINX Core Module — sendfile, aio & directio](https://nginx.org/en/docs/ngx_core_module.html), [NGINX Proxy Module — X-Accel-Redirect](https://nginx.org/en/docs/http/ngx_http_proxy_module.html), dan [NGINX Serving Static Content](https://nginx.org/en/docs/beginners_guide.html#static).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('linux-tuning', 'Tuning Linux & TCP untuk Server Sibuk', 'Naikkan batas sistem: file descriptor, backlog, dan parameter TCP agar server tahan ribuan koneksi bersamaan', 'https://images.unsplash.com/photo-1629654297299-c8506221ca97?auto=format&fit=crop&w=1200&q=80', 'Terminal Linux', 'Sistem Operasi', 'Mahir', '["linux","sysctl","tcp","kernel"]', 'Deni', '2026-11-13', '2026-11-13', NULL, 1, '["nginx-worker-tuning","database-pooling","nginx-rate-limit"]', 'Linux man-pages: sysctl', 'https://man7.org/linux/man-pages/man8/sysctl.8.html', '[{"level":2,"text":"Batas Default Linux Terlalu Kecil","type":"heading"},{"text":"Linux yang baru diinstal dikonfigurasi untuk penggunaan umum, bukan untuk server yang melayani ribuan koneksi bersamaan. Batas-batas defaultnya terlihat masuk akal untuk desktop, tetapi menjadi dinding yang tak terlihat saat traffic naik: jumlah file yang boleh dibuka satu proses dibatasi 1.024, antrean koneksi yang menunggu diterima dibatasi 128, dan rentang port untuk koneksi keluar hanya sekitar 28.000 port. Selama traffic masih kecil, semua batas ini tidak pernah terasa. Begitu server mulai sibuk, gejalanya muncul tiba-tiba dan membingungkan: error **Too many open files**, koneksi yang ditolak padahal CPU masih longgar, dan latency yang melonjak tanpa sebab yang jelas di aplikasi. Kabar baiknya, semua batas ini bisa diubah dalam hitungan menit melalui **sysctl** dan **ulimit**, tanpa perlu mengganti hardware atau menulis ulang aplikasi.","type":"paragraph"},{"text":"Artikel ini membahas empat kelompok penyetelan: batas file descriptor, antrean koneksi (backlog), parameter TCP untuk koneksi yang menumpuk di status TIME_WAIT, dan rentang port lokal. Semua perubahan dilakukan lewat file **/etc/sysctl.conf** agar bertahan setelah reboot, dan selalu diuji satu per satu sambil memantau metrik, bukan diubah sekaligus secara membabi buta.","type":"paragraph"},{"level":2,"text":"File Descriptor: ulimit dan fs.file-max","type":"heading"},{"text":"Di Linux, hampir semua hal adalah file: koneksi jaringan yang masuk, file yang sedang dibaca, socket antar proses, semuanya dihitung sebagai **file descriptor**. Setiap proses punya batas jumlah file descriptor yang boleh dibuka, dan nilai defaultnya adalah **1.024**. Untuk server web, satu koneksi klien memakai satu file descriptor, jadi NGINX atau aplikasi Node.js dengan batas 1.024 hanya bisa menangani sekitar 1.000 koneksi bersamaan sebelum mulai menolak koneksi baru dengan error `Too many open files`. Solusinya ada dua lapis: naikkan batas sistem secara global dengan **fs.file-max**, lalu naikkan batas per proses dengan **ulimit -n**. Untuk server sibuk, nilai 65.536 atau 100.000 per proses adalah titik awal yang wajar, dan pada server besar nilai 1.000.000 pun bukan hal aneh. Ingat, batas ini harus diubah di tempat proses dijalankan, misalnya di file unit systemd, bukan hanya di shell tempat kamu mengetik perintah, karena service yang dijalankan systemd tidak mewarisi ulimit dari shell kamu.","type":"paragraph"},{"code":"# Cek batas saat ini\nulimit -n                 # batas per proses (soft limit)\ncat /proc/sys/fs/file-max # batas global seluruh sistem\n\n# Naikkan batas global (sementara, hilang saat reboot)\nsysctl -w fs.file-max=1000000\n\n# Naikkan batas per proses untuk service systemd\n# Tambahkan di /etc/systemd/system/nginx.service.d/limits.conf:\n[Service]\nLimitNOFILE=100000\n\n# Terapkan dan verifikasi\n# systemctl daemon-reload && systemctl restart nginx\n# cat /proc/$(pidof nginx | cut -d'' '' -f1)/limits | grep \"Max open files\"","filename":"ulimit.sh","language":"bash","type":"code"},{"kind":"warning","text":"Mengubah ulimit di shell lalu me-restart service dari shell yang sama tidak menjamin service itu memakai batas baru kalau service dijalankan oleh systemd. Selalu ubah LimitNOFILE di unit systemd dan verifikasi dengan membaca /proc/<pid>/limits.","title":"Ulimit shell bukan ulimit service","type":"callout"},{"level":2,"text":"Backlog: somaxconn dan NGINX","type":"heading"},{"text":"Ketika klien terhubung ke server, kernel menaruh koneksi itu di **antrean backlog** sambil menunggu aplikasi menerimanya. Ukuran antrean ini diatur oleh **net.core.somaxconn**, yang nilai defaultnya hanya **128**. Pada server sibuk, 128 slot antrean terisi dalam sekejap saat ada lonjakan traffic, dan koneksi berikutnya langsung ditolak dengan **connection refused** atau reset, padahal CPU dan RAM server masih longgar. Ini adalah salah satu penyebab paling umum dari error koneksi yang muncul mendadak saat traffic naik. Naikkan `somaxconn` ke 4.096 atau 65.535, lalu samakan dengan pengaturan backlog di aplikasi: di NGINX, parameter `backlog` pada directive `listen` (misalnya `listen 80 backlog=4096;`), dan di Node.js atau Go, parameter backlog pada pemanggilan `listen`. Kalau kernel mengizinkan 4.096 tetapi aplikasi hanya meminta 128, batas yang berlaku tetap 128.","type":"paragraph"},{"code":"# Naikkan antrean koneksi kernel\nsysctl -w net.core.somaxconn=4096\nsysctl -w net.core.netdev_max_backlog=4096\n\n# Samakan backlog di NGINX (nginx.conf)\n# server {\n#     listen 80 backlog=4096;\n#     listen 443 ssl backlog=4096;\n#     ...\n# }\n\n# Cek koneksi yang tertolak karena backlog penuh\n# ss -s | grep -i drop\n# nstat -az | grep -i listenoverflows","filename":"backlog.sh","language":"bash","type":"code"},{"level":2,"text":"TIME_WAIT: Koneksi yang Menumpuk","type":"heading"},{"text":"Setelah koneksi TCP ditutup, ia tidak langsung hilang. Ia masuk ke status **TIME_WAIT** selama 60 detik secara default, untuk memastikan tidak ada paket yang tertinggal di jaringan. Ini tidak masalah untuk koneksi yang masuk, tetapi menjadi masalah besar untuk server yang banyak membuka koneksi **keluar**, misalnya reverse proxy ke upstream, aplikasi ke database, atau worker ke API pihak ketiga. Setiap koneksi keluar yang ditutup menempati satu port lokal selama 60 detik, dan rentang port lokal default hanya sekitar 28.000 port (32768-60999). Dengan 1.000 koneksi keluar per detik, seluruh port habis dalam 28 detik dan koneksi baru gagal dengan error `Cannot assign requested address`. Solusinya adalah mengaktifkan **tcp_tw_reuse**, yang mengizinkan kernel memakai ulang socket TIME_WAIT untuk koneksi keluar yang baru, dan memperpendek **tcp_fin_timeout** dari 60 detik menjadi 15 sampai 30 detik.","type":"paragraph"},{"code":"# Izinkan pemakaian ulang socket TIME_WAIT untuk koneksi keluar\nsysctl -w net.ipv4.tcp_tw_reuse=1\n\n# Persingkat waktu tunggu penutupan koneksi dari 60 ke 30 detik\nsysctl -w net.ipv4.tcp_fin_timeout=30\n\n# Perluas rentang port lokal dari 28 ribu menjadi ~48 ribu\nsysctl -w net.ipv4.ip_local_port_range=\"1024 65000\"\n\n# Cek berapa banyak socket yang sedang TIME_WAIT\n# ss -tan state time-wait | wc -l\n# ss -tan | awk ''{print $1}'' | sort | uniq -c","filename":"timewait.sh","language":"bash","type":"code"},{"kind":"tip","text":"Jangan aktifkan tcp_tw_recycle, parameter itu sudah dihapus dari kernel Linux modern karena merusak koneksi dari balik NAT. Yang aman dipakai adalah tcp_tw_reuse, dan hanya berpengaruh pada koneksi keluar.","title":"tw_reuse ya, tw_recycle tidak","type":"callout"},{"level":2,"text":"Menyimpan Permanen di sysctl.conf","type":"heading"},{"text":"Semua perintah `sysctl -w` di atas hanya berlaku sampai server di-reboot. Supaya bertahan, tulis semuanya ke file **/etc/sysctl.conf** atau file terpisah di **/etc/sysctl.d/**, lalu terapkan dengan `sysctl -p`. Biasakan memberi komentar pada setiap baris agar enam bulan kemudian kamu masih ingat kenapa nilainya diubah. Setelah menerapkan, verifikasi dengan `sysctl -a | grep` untuk memastikan nilainya benar-benar berubah, dan pantau selama beberapa hari sebelum mengubah parameter lain. Mengubah lima parameter sekaligus lalu terjadi masalah akan membuatmu tidak tahu parameter mana yang menjadi penyebabnya.","type":"paragraph"},{"code":"# /etc/sysctl.d/99-server-tuning.conf\n# Batas file descriptor global\nfs.file-max = 1000000\n\n# Antrean koneksi masuk\nnet.core.somaxconn = 4096\nnet.core.netdev_max_backlog = 4096\n\n# Penanganan koneksi TIME_WAIT dan port lokal\nnet.ipv4.tcp_tw_reuse = 1\nnet.ipv4.tcp_fin_timeout = 30\nnet.ipv4.ip_local_port_range = 1024 65000\n\n# Terapkan tanpa reboot:\n# sysctl -p /etc/sysctl.d/99-server-tuning.conf\n# Verifikasi:\n# sysctl net.core.somaxconn net.ipv4.tcp_tw_reuse","filename":"99-server-tuning.conf","language":"bash","type":"code"},{"level":2,"text":"Cara Memantau Hasilnya","type":"heading"},{"text":"Penyetelan tanpa pemantauan adalah tebak-tebakan. Tiga perintah ini cukup untuk memverifikasi apakah perubahanmu bekerja. Perintah **ss -s** menunjukkan ringkasan semua socket, termasuk berapa banyak yang TIME_WAIT dan berapa yang terbuang karena backlog penuh. Perintah **nstat -az** menampilkan counter kernel seperti `ListenOverflows` (koneksi yang ditolak karena backlog penuh) dan `TCPTimeWaitOverflow`; kalau angka ini terus bertambah setelah kamu menaikkan somaxconn, berarti backlog masih kurang atau aplikasi tidak menerima koneksi cukup cepat. Perintah **ulimit -n** dan membaca `/proc/<pid>/limits` memastikan proses benar-benar berjalan dengan batas baru. Catat angka sebelum dan sesudah perubahan, karena itulah bukti bahwa tuning-nya berhasil, bukan sekadar perasaan.","type":"paragraph"},{"code":"# Ringkasan socket: berapa TIME_WAIT, berapa yang terbuang\nss -s\n\n# Counter kernel: ListenOverflows harus berhenti bertambah\nnstat -az | grep -E ''ListenOverflows|TCPTimeWaitOverflow|TCPReqQFullDoCookies''\n\n# Batas file descriptor proses NGINX yang sedang berjalan\ncat /proc/$(pidof nginx | cut -d'' '' -f1)/limits | grep ''Max open files''\n\n# Berapa file descriptor yang sedang dipakai seluruh sistem\ncat /proc/sys/fs/file-nr","filename":"monitoring.sh","language":"bash","type":"code"},{"headers":["Parameter","Default","Server sibuk","Efek"],"rows":[["fs.file-max","~200 ribu","1.000.000","Mencegah error Too many open files"],["ulimit -n per proses","1.024","65.536-100.000","~65 ribu koneksi per proses"],["net.core.somaxconn","128","4.096","Lonjakan koneksi tidak langsung ditolak"],["tcp_fin_timeout","60 detik","30 detik","Socket TIME_WAIT lebih cepat bebas"],["ip_local_port_range","~28 ribu port","~48 ribu port","Koneksi keluar 70% lebih banyak"]],"type":"table"},{"kind":"info","text":"Nilai di tabel adalah titik awal yang aman untuk kebanyakan server. Server dengan puluhan ribu koneksi bersamaan mungkin butuh somaxconn 65.535 dan ulimit 1.000.000 — naikkan bertahap dan pantau dengan ss dan nstat.","title":"Mulai dari nilai aman, naikkan bertahap","type":"callout"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi dan panduan lanjutan tersedia di [Linux man-pages: sysctl](https://man7.org/linux/man-pages/man8/sysctl.8.html) dan [Linux man-pages: tcp](https://man7.org/linux/man-pages/man7/tcp.7.html).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-cache', 'Cache di NGINX: proxy_cache & fastcgi_cache', 'Biarkan NGINX menjawab dari cache: kurangi beban upstream sampai 90% untuk konten yang sering diminta', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80', 'Ruang server', 'NGINX', 'Menengah', '["nginx","cache","proxy-cache","fastcgi-cache"]', 'Deni', '2026-11-13', '2026-11-13', 'nginx-overview', 1, '["nginx-overview","nginx-compression","redis-cache"]', 'NGINX Caching Guide', 'https://nginx.org/en/docs/http/ngx_http_proxy_module.html', '[{"level":2,"text":"Cara Kerja Cache NGINX","type":"heading"},{"text":"Ketika NGINX bertindak sebagai reverse proxy, setiap request diteruskan ke upstream — PHP-FPM, aplikasi Node.js, atau server aplikasi lain — yang lalu menghabiskan waktu CPU dan query database untuk menghasilkan respons. Kalau respons itu diminta lagi lima detik kemudian oleh pengguna lain, NGINX akan mengulang seluruh proses dari awal. Cache memutus rantai ini: respons pertama disimpan di memori atau disk, dan request berikutnya untuk URL yang sama dijawab langsung dari cache tanpa menyentuh upstream sama sekali. Hasilnya dramatis: untuk halaman yang sering dibuka, beban upstream bisa turun **70–90%** dan waktu respons (TTFB) turun dari 200–500 ms menjadi **10–30 ms**. Inilah kenapa cache hampir selalu menjadi langkah tuning pertama yang paling berdampak.","type":"paragraph"},{"code":"http {\n    # Zona cache: 10 MB metadata (~80 ribu key), maks 1 GB file, hapus yang tak dipakai 60 menit\n    proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=app_cache:10m max_size=1g inactive=60m use_temp_path=off;\n\n    server {\n        listen 80;\n        server_name contoh.com;\n\n        location / {\n            proxy_cache app_cache;\n            proxy_cache_valid 200 301 302 10m;\n            proxy_cache_valid 404 1m;\n            proxy_cache_use_stale error timeout updating http_500 http_502 http_503;\n            proxy_pass http://127.0.0.1:8080;\n            add_header X-Cache-Status $upstream_cache_status;\n        }\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Memahami proxy_cache_path","type":"heading"},{"text":"Satu baris `proxy_cache_path` menentukan hampir semua perilaku cache. Parameter `levels=1:2` mengatur struktur folder penyimpanan supaya satu folder tidak berisi terlalu banyak file (penting saat cache berisi ratusan ribu objek). `keys_zone` memberi nama zona dan ukuran memori untuk metadata — patokannya **1 MB metadata untuk sekitar 8.000 key**, jadi 10 MB cukup untuk kurang lebih 80.000 URL yang di-cache. `max_size` adalah batas total ukuran file cache di disk; begitu penuh, NGINX menghapus cache yang paling lama tidak dipakai. `inactive` menentukan berapa lama sebuah objek boleh tidak disentuh sebelum dihapus — bedakan dengan masa validasi: objek yang sudah kedaluwarsa tapi masih dalam masa `inactive` tetap tersimpan dan bisa disajikan sebagai `stale` saat upstream sedang bermasalah.","type":"paragraph"},{"headers":["Directive","Fungsi","Nilai awal yang wajar"],"rows":[["levels","Struktur folder cache di disk","1:2"],["keys_zone","Nama zona + memori metadata","10m (~80 ribu key)"],["max_size","Batas total ukuran cache","1g"],["inactive","Hapus objek yang lama tak dipakai","60m"],["use_temp_path","Tulis langsung ke folder cache","off"]],"type":"table"},{"level":2,"text":"Cache Key dan Validitas","type":"heading"},{"text":"NGINX memutuskan apakah sebuah request adalah HIT atau MISS berdasarkan **cache key** — dan kunci bawaan sudah cukup baik untuk kebanyakan kasus: kombinasi skema, metode request, host, dan URI lengkap dengan query string. Tapi ada situasi yang butuh kunci khusus, misalnya situs dengan banyak bahasa yang membedakan konten lewat header `Accept-Language`, atau API yang membedakan respons berdasarkan token pengguna. Di sisi lain, `proxy_cache_valid` menentukan berapa lama setiap kode status boleh disimpan: respons 200 bisa disimpan 10 menit, sementara 404 cukup 1 menit supaya halaman yang salah ketik tidak lama-lama menghantui cache. Satu aturan emas: **jangan pernah meng-cache respons yang mengandung data pribadi** — halaman akun, keranjang belanja, atau hasil pencarian yang spesifik untuk satu pengguna.","type":"paragraph"},{"code":"# Cache key kustom: bedakan berdasarkan bahasa dari header\nproxy_cache_key ''$scheme$request_method$host$request_uri$http_accept_language'';\n\n# Validitas berbeda per kode status\nproxy_cache_valid 200 301 302 10m;\nproxy_cache_valid 404 1m;\nproxy_cache_valid any 0;\n\n# Jangan simpan respons yang mengandung Set-Cookie (data sesi)\nproxy_no_cache $cookie_session $http_authorization;\nproxy_cache_bypass $cookie_session $http_authorization;","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"fastcgi_cache untuk PHP","type":"heading"},{"text":"Kalau aplikasimu berjalan di PHP-FPM — WordPress, Laravel, atau aplikasi PHP lainnya — NGINX tidak memakai `proxy_cache` melainkan `fastcgi_cache`, karena protokol ke PHP-FPM adalah FastCGI, bukan HTTP proxy. Cara kerjanya sama persis, hanya nama directive-nya berbeda. Ini penting karena banyak tutorial mencampuradukkan keduanya: konfigurasi `proxy_cache` tidak akan berpengaruh sama sekali pada request yang diteruskan lewat `fastcgi_pass`. Untuk WordPress, kombinasi `fastcgi_cache` dengan plugin cache yang mengirim header yang tepat bisa membuat halaman artikel yang tadinya butuh 300 ms dari PHP menjadi **15 ms dari cache**.","type":"paragraph"},{"code":"http {\n    fastcgi_cache_path /var/cache/nginx/fastcgi levels=1:2 keys_zone=php_cache:10m max_size=1g inactive=60m use_temp_path=off;\n\n    server {\n        listen 80;\n        server_name contoh.com;\n        root /var/www/contoh.com;\n\n        location ~ \\.php$ {\n            fastcgi_cache php_cache;\n            fastcgi_cache_valid 200 10m;\n            fastcgi_cache_use_stale error timeout updating;\n            fastcgi_cache_bypass $cookie_session $http_authorization;\n            fastcgi_no_cache $cookie_session $http_authorization;\n            include fastcgi_params;\n            fastcgi_pass unix:/run/php/php8.3-fpm.sock;\n            add_header X-Cache-Status $upstream_cache_status;\n        }\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"kind":"info","text":"`proxy_cache` dipakai saat NGINX meneruskan request lewat `proxy_pass` (ke Node.js, Go, Python, atau server lain), sedangkan `fastcgi_cache` dipakai saat meneruskan lewat `fastcgi_pass` (ke PHP-FPM). Jangan tertukar: directive yang salah tidak menimbulkan error, tapi cache-mu tidak akan pernah terisi dan kamu akan bingung kenapa semua request tetap MISS.","title":"proxy_cache vs fastcgi_cache","type":"callout"},{"level":2,"text":"Bypass dan Purge: Kapan Cache Harus Dilewati","type":"heading"},{"text":"Cache yang baik harus tahu kapan **tidak** dipakai. Dua directive yang bekerja berpasangan adalah `proxy_cache_bypass` (lewati cache saat membaca, tapi tetap simpan hasilnya untuk request berikutnya) dan `proxy_no_cache` (jangan simpan hasilnya sama sekali). Keduanya biasanya diisi kondisi yang sama: ada cookie sesi, ada header Authorization, atau ada parameter khusus seperti `?nocache=1` untuk admin. Untuk membersihkan cache secara manual — misalnya setelah artikel diperbarui — cara paling sederhana adalah menghapus file cache terkait dari disk dan me-reload NGINX, atau memasang modul `ngx_cache_purge` bila kamu butuh endpoint purge lewat HTTP. Alternatif yang lebih aman untuk konten yang sering berubah adalah masa validasi yang pendek (1–5 menit) dikombinasikan dengan `proxy_cache_use_stale updating`, supaya pengunjung tetap mendapat respons cepat selagi NGINX memperbarui cache di latar belakang.","type":"paragraph"},{"code":"# Lewati cache untuk pengguna login & admin\nmap $cookie_session $skip_cache {\n    default 0;\n    ~.+ 1;\n}\n\nserver {\n    location / {\n        proxy_cache app_cache;\n        proxy_cache_bypass $skip_cache $arg_nocache;\n        proxy_no_cache $skip_cache $arg_nocache;\n        proxy_pass http://127.0.0.1:8080;\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Memverifikasi HIT dan MISS","type":"heading"},{"text":"Cache yang tidak diverifikasi sama saja dengan tidak ada. Cara paling cepat adalah menambahkan header `X-Cache-Status` dengan nilai `$upstream_cache_status`, lalu meminta URL yang sama dua kali dengan `curl`. Request pertama seharusnya `MISS` (NGINX mengambil dari upstream dan menyimpan), request kedua `HIT` (dijawab dari cache). Nilai lain yang mungkin muncul: `BYPASS` (cache sengaja dilewati), `EXPIRED` (cache kedaluwarsa dan sedang diperbarui), dan `STALE` (disajikan cache lama karena upstream sedang error). Untuk target angka: website konten sebaiknya mencapai **hit ratio 80–90%** — artinya dari 100 request, 80–90 dijawab dari cache. Kamu bisa menghitung hit ratio dari access log dengan memfilter nilai header tersebut, atau dari metrik `stub_status` dan log monitoring yang sudah kamu pasang.","type":"paragraph"},{"code":"# Request pertama: MISS, request kedua: HIT\ncurl -I https://contoh.com/artikel-populer\n# X-Cache-Status: MISS\n\ncurl -I https://contoh.com/artikel-populer\n# X-Cache-Status: HIT\n\n# Hitung hit ratio dari access log (butuh log_format dengan $upstream_cache_status)\nawk ''{print $NF}'' /var/log/nginx/access.log | sort | uniq -c","filename":"verifikasi-cache.sh","language":"bash","type":"code"},{"kind":"tip","text":"Target hit ratio 80–90% itu realistis untuk website konten, blog, dan katalog produk. Kalau hit ratio-mu di bawah 50%, periksa tiga hal: apakah masa validasi terlalu pendek, apakah cache key terlalu spesifik (misalnya mengandung query string acak dari iklan), atau apakah sebagian besar traffic-mu memang konten personal yang tidak boleh di-cache. Untuk API, hit ratio 40–60% saja sudah sangat membantu karena setiap HIT berarti satu query database yang tidak dieksekusi.","title":"Target Hit Ratio","type":"callout"},{"kind":"warning","text":"Kesalahan paling berbahaya dalam caching adalah meng-cache konten yang seharusnya personal. Bayangkan halaman akun pengguna A tersimpan di cache lalu disajikan ke pengguna B — ini kebocoran data. Selalu pastikan respons yang mengandung `Set-Cookie`, header `Authorization`, atau cookie sesi tidak pernah masuk cache. Aturan praktis: kalau responsnya berbeda untuk setiap pengguna, jangan di-cache; kalau sama untuk semua orang, cache selama mungkin.","title":"Jangan Cache Konten Personal","type":"callout"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi modul proxy dan cache NGINX: [NGINX Caching Guide](https://nginx.org/en/docs/http/ngx_http_proxy_module.html). Untuk FastCGI, lihat juga dokumentasi modul FastCGI di situs yang sama.","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-compression', 'Kompresi Gzip & Brotli di NGINX', 'Perkecil ukuran transfer sampai 70-80%: halaman lebih cepat dimuat, bandwidth lebih hemat', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80', 'Grafik analitik', 'NGINX', 'Pemula', '["nginx","gzip","brotli","kompresi"]', 'Deni', '2026-11-13', '2026-11-13', 'nginx-overview', 3, '["nginx-overview","nginx-cache","file-download"]', 'NGINX Gzip Module', 'https://nginx.org/en/docs/http/ngx_http_gzip_module.html', '[{"level":2,"text":"Kenapa Kompresi Berdampak Besar","type":"heading"},{"text":"Sebagian besar yang dikirim server ke browser adalah teks: HTML, CSS, dan JavaScript. Teks sangat bisa dikompresi karena penuh pola berulang — spasi, tag penutup, nama class yang sama muncul puluhan kali. Gzip biasanya memangkas ukuran file teks **70–80%**, dan Brotli bisa lebih kecil lagi sekitar 15–20% dibanding gzip. Artinya halaman 200 KB menjadi sekitar 40–50 KB saat transit. Untuk pengguna dengan koneksi 4G atau internet yang tidak stabil, ini perbedaan antara halaman yang muncul dalam 1 detik dan halaman yang baru selesai setelah 4 detik. Yang menarik: kompresi adalah salah satu teknik tuning termurah — satu blok konfigurasi, tanpa perubahan kode aplikasi, dan hasilnya langsung terasa di semua halaman sekaligus.","type":"paragraph"},{"headers":["Jenis file","Ukuran awal","Setelah gzip","Setelah Brotli"],"rows":[["HTML (100 KB)","100 KB","~25 KB","~20 KB"],["CSS (150 KB)","150 KB","~30 KB","~25 KB"],["JavaScript (300 KB)","300 KB","~90 KB","~75 KB"],["JSON API (50 KB)","50 KB","~10 KB","~8 KB"],["Gambar JPG/PNG","—","Jangan dikompresi","Jangan dikompresi"]],"type":"table"},{"level":2,"text":"Mengaktifkan Gzip","type":"heading"},{"text":"Mengaktifkan gzip di NGINX hanya butuh beberapa baris di blok `http` supaya berlaku untuk semua server. Directive terpenting adalah `gzip_comp_level`, dengan skala 1 sampai 9: level 1 mengompresi paling cepat tapi hasilnya paling besar, level 9 hasilnya paling kecil tapi CPU yang dipakai melonjak. Titik manis untuk kebanyakan server ada di **level 5 atau 6** — di atas itu, penghematan ukuran tambahan hanya 1–2% sementara waktu CPU yang dibutuhkan bisa naik dua kali lipat. Selain itu, `gzip_vary` memberitahu cache di tengah jalan (CDN atau proxy) bahwa respons ini berbeda-beda tergantung header `Accept-Encoding`, supaya client yang tidak mendukung gzip tidak menerima file yang sudah dikompresi secara tidak sengaja.","type":"paragraph"},{"code":"http {\n    gzip on;\n    gzip_comp_level 6;\n    gzip_vary on;\n    gzip_proxied any;\n    gzip_min_length 1024;\n    gzip_buffers 16 8k;\n    gzip_http_version 1.1;\n\n    # Hanya kompres file teks — gambar & video sudah terkompresi\n    gzip_types\n        text/plain\n        text/css\n        text/javascript\n        application/javascript\n        application/json\n        application/xml\n        image/svg+xml;\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Jenis File dan Ukuran Minimum","type":"heading"},{"text":"Tidak semua file layak dikompresi. `gzip_types` menentukan tipe MIME apa saja yang dikompresi — dan daftarnya harus eksplisit, karena secara bawaan NGINX hanya mengompresi `text/html`. Tambahkan CSS, JavaScript, JSON, XML, dan SVG. Yang tidak boleh masuk daftar adalah format yang sudah terkompresi secara bawaan: JPG, PNG, WebP, MP4, ZIP, dan font WOFF2. Mengompresi file-file ini tidak mengecilkan ukuran — malah bisa sedikit membesar — dan hanya membuang CPU. Aturan kedua adalah `gzip_min_length`: file di bawah **1 KB** sebaiknya tidak dikompresi karena overhead header kompresi bisa lebih besar daripada penghematannya. Aturan ketiga adalah `gzip_proxied any`: tanpa ini, NGINX tidak akan mengompresi respons yang datang dari upstream (proxy) — padahal sebagian besar respons dinamis memang datang dari sana.","type":"paragraph"},{"code":"# Periksa tipe MIME yang dikompresi — tambahkan yang kurang\n# text/html sudah aktif secara bawaan, tidak perlu ditulis\ngzip_types\n    text/plain\n    text/css\n    text/javascript\n    application/javascript\n    application/json\n    application/xml\n    application/rss+xml\n    image/svg+xml;\n\n# Jangan kompres file kecil & respons dari cache tertentu\ngzip_min_length 1024;\ngzip_proxied any;\ngzip_disable ''msie6''; # Browser IE6 kuno tidak mendukung gzip dengan benar","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"gzip_static: Kompresi Sekali, Sajikan Berkali-kali","type":"heading"},{"text":"Gzip biasa mengompresi file setiap kali ada request — untuk file statis yang tidak pernah berubah, itu pemborosan CPU yang berulang. `gzip_static` membalik logikanya: kamu mengompresi file sekali di depan (misalnya saat proses build atau deploy), menyimpan versi `.gz`-nya di samping file asli, dan NGINX langsung menyajikan file `.gz` itu tanpa mengompresi apa pun. Keuntungannya ganda: CPU tidak bekerja sama sekali saat menyajikan file, dan kamu bisa memakai level kompresi 9 (yang paling kecil) karena kompresi hanya dilakukan sekali saat build, bukan setiap request. Untuk aset hasil build frontend (JavaScript dan CSS hasil bundling), cara ini hampir selalu lebih baik daripada gzip dinamis.","type":"paragraph"},{"code":"# Kompresi semua aset statis saat deploy (level 9, sekali saja)\nfind /var/www/contoh.com/static -type f \\( -name ''*.js'' -o -name ''*.css'' -o -name ''*.html'' -o -name ''*.svg'' \\) -exec gzip -9 -k -f {} \\;\n\n# NGINX menyajikan file .gz bila tersedia\nserver {\n    location /static/ {\n        gzip_static on;\n        gzip on;\n        expires 30d;\n        add_header Cache-Control ''public, immutable'';\n    }\n}","filename":"deploy.sh","language":"bash","type":"code"},{"level":2,"text":"Brotli: Lebih Kecil dari Gzip","type":"heading"},{"text":"Brotli adalah algoritma kompresi yang dikembangkan Google dan didukung semua browser modern. Pada level kompresi yang sebanding, Brotli menghasilkan file **15–20% lebih kecil** dibanding gzip — untuk JavaScript 300 KB, selisihnya bisa 15 KB per halaman, dan untuk situs dengan jutaan kunjungan, penghematan bandwidth itu sangat terasa. Kekurangannya: Brotli bukan modul bawaan NGINX, jadi harus dipasang dari paket sistem operasi (`libnginx-mod-http-brotli-static` di Debian/Ubuntu) atau dikompilasi dari source. Setelah terpasang, konfigurasinya mirip gzip: aktifkan `brotli`, set level kompresi ke 4–6, dan daftarkan tipe file yang sama. Strategi terbaik adalah mengaktifkan **keduanya**: NGINX akan menyajikan Brotli ke browser yang mendukungnya, dan jatuh kembali ke gzip untuk browser lama — jadi tidak ada pengguna yang dirugikan.","type":"paragraph"},{"code":"# Debian/Ubuntu: pasang modul Brotli untuk NGINX\nsudo apt install libnginx-mod-http-brotli-static\n\n# Cek modul terpasang\nnginx -V 2>&1 | grep -o brotli","filename":"install-brotli.sh","language":"bash","type":"code"},{"code":"http {\n    # Brotli dulu (lebih kecil), gzip sebagai fallback\n    brotli on;\n    brotli_comp_level 6;\n    brotli_types\n        text/plain\n        text/css\n        text/javascript\n        application/javascript\n        application/json\n        application/xml\n        image/svg+xml;\n\n    gzip on;\n    gzip_comp_level 6;\n    gzip_vary on;\n    gzip_types\n        text/plain\n        text/css\n        text/javascript\n        application/javascript\n        application/json;\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"kind":"tip","text":"Kombinasi ideal untuk kebanyakan situs: Brotli level 6 untuk browser modern, gzip level 6 sebagai fallback, dan `gzip_static` atau `brotli_static` untuk aset hasil build yang tidak berubah. Dengan kombinasi ini, pengguna Chrome dan Firefox mendapat file Brotli yang paling kecil, pengguna browser lama tetap mendapat gzip, dan file statis tidak menghabiskan CPU sama sekali karena sudah dikompresi sejak deploy.","title":"Kombinasi Ideal","type":"callout"},{"level":2,"text":"Memverifikasi Kompresi","type":"heading"},{"text":"Jangan percaya konfigurasi sebelum diuji. Cara paling cepat adalah `curl` dengan header `Accept-Encoding: gzip` dan melihat header respons: kalau kompresi aktif, respons akan mengandung `Content-Encoding: gzip` (atau `br` untuk Brotli) dan `Content-Length` yang jauh lebih kecil daripada ukuran asli. Ulangi dengan `Accept-Encoding: br` untuk memastikan Brotli juga jalan. Untuk memastikan tidak ada yang salah, bandingkan juga ukuran file asli di disk dengan ukuran transfer: halaman HTML 100 KB seharusnya terkirim sekitar 20–30 KB. Kalau `Content-Encoding` tidak muncul, periksa tiga hal: apakah `gzip_types` mencakup tipe MIME halaman itu, apakah ukurannya di atas `gzip_min_length`, dan apakah responsnya datang dari upstream tanpa `gzip_proxied any`.","type":"paragraph"},{"code":"# Minta gzip dan lihat header respons\ncurl -H ''Accept-Encoding: gzip'' -I https://contoh.com/\n# Content-Encoding: gzip\n# Content-Length: 24512 (dari 100 KB asli)\n\n# Minta Brotli\ncurl -H ''Accept-Encoding: br'' -I https://contoh.com/\n# Content-Encoding: br\n\n# Bandingkan ukuran transfer dengan dan tanpa kompresi\ncurl -o /dev/null -s -w ''Tanpa kompresi: %{size_download} byte\\n'' https://contoh.com/\ncurl -H ''Accept-Encoding: gzip'' -o /dev/null -s -w ''Dengan gzip: %{size_download} byte\\n'' https://contoh.com/","filename":"verifikasi-kompresi.sh","language":"bash","type":"code"},{"kind":"warning","text":"Kompresi bukan tanpa biaya: setiap respons teks harus dikompresi oleh CPU sebelum dikirim. Di server dengan CPU kecil dan traffic sangat tinggi, gzip level 9 bisa menjadi bottleneck baru — CPU penuh hanya untuk mengompresi. Itu kenapa level 5–6 direkomendasikan, dan kenapa file statis sebaiknya memakai `gzip_static`. Satu pengecualian lain: jangan mengompresi respons yang sudah terenkripsi atau token keamanan (misalnya respons login) dengan kompresi yang bisa dieksploitasi lewat serangan BREACH — untuk endpoint sensitif, lebih aman mematikan kompresi.","title":"Biaya CPU dan Pengecualian","type":"callout"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi modul gzip NGINX: [NGINX Gzip Module](https://nginx.org/en/docs/http/ngx_http_gzip_module.html). Untuk Brotli, lihat repositori modul ngx_brotli dan dokumentasi paket distribusi Linux yang kamu pakai.","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-load-balancing', 'Load Balancing NGINX', 'Sebar beban ke banyak server: round-robin, least_conn, ip_hash, dan health check', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80', 'Dashboard monitoring', 'NGINX', 'Menengah', '["nginx","load-balancing","upstream","high-availability"]', 'Deni', '2026-11-13', '2026-11-13', 'nginx-reverse-proxy-tuning', 1, '["nginx-reverse-proxy-tuning","nginx-worker-tuning","database-pooling"]', 'NGINX Load Balancing', 'https://nginx.org/en/docs/http/load_balancing.html', '[{"text":"Satu server punya batas: CPU, memory, dan bandwidth-nya terbatas. Saat traffic melewati batas itu, ada dua jalan — **scale up** (server lebih besar) atau **scale out** (server lebih banyak). Load balancing adalah cara scale out: NGINX membagi request ke beberapa server backend, sehingga kapasitas total menjadi jumlah semua server, dan satu server mati tidak berarti layanan mati. Dengan dua server 4 core, kapasitas yang tadinya **5.000 request per detik** bisa menjadi hampir 10.000 — plus ketahanan terhadap kegagalan.","type":"paragraph"},{"kind":"info","text":"Load balancer NGINX bekerja di layer 7 (HTTP): ia membaca request, memilih satu server upstream, meneruskan request, dan mengembalikan response. Karena ia memahami HTTP, ia bisa membuat keputusan cerdas — mis. mengirim request berat ke server yang paling kosong, atau memastikan satu pengguna selalu sampai ke server yang sama.","title":"Load balancer layer 7","type":"callout"},{"level":2,"text":"Blok Upstream: Daftar Server Backend","type":"heading"},{"text":"Semua berawal dari blok `upstream`: daftar server yang akan menerima beban. Secara default NGINX memakai **round-robin** — request dibagi rata bergiliran ke semua server. Ini sudah cukup untuk server yang spesifikasinya sama dan request yang bebannya merata. Tapi dunia nyata jarang semerata itu, dan di sinilah metode lain berperan.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/app.conf\nupstream app_backend {\n    server 10.0.0.11:3000;\n    server 10.0.0.12:3000;\n    server 10.0.0.13:3000;\n}\n\nserver {\n    listen 443 ssl;\n    server_name api.contoh.id;\n\n    location / {\n        proxy_pass http://app_backend;\n        proxy_http_version 1.1;\n        proxy_set_header Connection \"\";\n    }\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"level":2,"text":"Memilih Metode: round-robin, least_conn, ip_hash, hash","type":"heading"},{"text":"Empat metode ini menutupi hampir semua kebutuhan. **Round-robin** (default) membagi rata tanpa melihat beban — bagus kalau semua server sama kuat dan request seragam. **least_conn** mengirim request baru ke server dengan koneksi aktif paling sedikit — ini pilihan terbaik saat durasi request bervariasi (ada request 50 ms dan ada yang 5 detik), karena server yang sedang sibuk tidak ditambah beban. Di benchmark dengan request campuran, `least_conn` menurunkan latency p99 sampai **30–40%** dibanding round-robin. **ip_hash** mengikat satu IP klien ke satu server — berguna kalau aplikasi menyimpan session di memory server (bukan di Redis). **hash** memungkinkan routing berdasarkan kunci apa pun, mis. `hash $request_uri consistent` supaya URL yang sama selalu ke server yang sama (berguna untuk cache di backend).","type":"paragraph"},{"headers":["Metode","Cara kerja","Cocok untuk"],"rows":[["`round-robin` (default)","Bagi rata bergiliran","Server identik, request seragam"],["`least_conn`","Ke server dengan koneksi aktif paling sedikit","Request berdurasi bervariasi, p99 penting"],["`ip_hash`","IP klien yang sama selalu ke server yang sama","Session di memory server (tanpa Redis)"],["`hash $request_uri consistent`","Kunci yang sama selalu ke server yang sama","Cache per-server, routing berdasarkan URL"],["`random` (NGINX 1.15.1+)","Pilih acak dari 2 server, ambil yang lebih kosong","Alternatif ringan untuk least_conn"]],"type":"table"},{"code":"# least_conn: terbaik untuk API dengan durasi request bervariasi\nupstream app_backend {\n    least_conn;\n    server 10.0.0.11:3000;\n    server 10.0.0.12:3000;\n    server 10.0.0.13:3000;\n    keepalive 32;\n}\n\n# ip_hash: session menempel di satu server\nupstream legacy_app {\n    ip_hash;\n    server 10.0.0.21:8080;\n    server 10.0.0.22:8080;\n}\n\n# hash konsisten: URL yang sama selalu ke server yang sama\nupstream cache_nodes {\n    hash $request_uri consistent;\n    server 10.0.0.31:8000;\n    server 10.0.0.32:8000;\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"kind":"warning","text":"`ip_hash` bukan solusi session yang ideal: kalau satu server mati, semua pengguna yang menempel di server itu kehilangan session dan harus login ulang. Solusi jangka panjangnya adalah menyimpan session di tempat terpusat (Redis atau database), lalu memakai `least_conn` — server mana pun bisa melayani siapa pun, dan tidak ada pengguna yang kehilangan session saat satu server down.","title":"ip_hash itu jalan pintas, bukan solusi","type":"callout"},{"level":2,"text":"Weight, max_fails, dan Backup Server","type":"heading"},{"text":"Tidak semua server sama kuat. Parameter `weight` membagi traffic secara proporsional: server dengan `weight=3` menerima tiga kali lebih banyak request dibanding `weight=1`. Ini berguna saat kamu mencampur server lama dan baru, atau saat melakukan migrasi bertahap. Parameter `max_fails` dan `fail_timeout` adalah health check pasif bawaan NGINX open source: kalau server gagal menjawab 3 kali dalam 30 detik, NGINX menganggapnya mati dan berhenti mengirim traffic selama 30 detik, lalu mencoba lagi.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/app.conf\nupstream app_backend {\n    least_conn;\n    # Server baru (8 core) dapat beban 3x lipat dari server lama (4 core)\n    server 10.0.0.11:3000 weight=3 max_fails=3 fail_timeout=30s;\n    server 10.0.0.12:3000 weight=1 max_fails=3 fail_timeout=30s;\n    # Server cadangan: hanya dipakai kalau semua server utama down\n    server 10.0.0.13:3000 backup;\n    # Server dalam maintenance: jangan kirim traffic sama sekali\n    # server 10.0.0.14:3000 down;\n    keepalive 32;\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"text":"Pola `backup` sangat berguna saat deploy: sebelum mematikan server utama untuk update, pindahkan traffic dulu dengan menandai server sebagai `down` lalu `nginx -s reload` — NGINX akan mengalihkan traffic tanpa memutus koneksi yang sedang berjalan. Ini yang membuat deploy tanpa downtime menjadi mungkin tanpa alat tambahan. Untuk health check **aktif** (NGINX yang proaktif mengecek `/health` tiap beberapa detik, bukan menunggu ada request gagal), kamu butuh NGINX Plus atau modul pihak ketiga — di open source, kombinasi `max_fails` + `proxy_next_upstream` sudah cukup untuk kebanyakan kasus.","type":"paragraph"},{"level":2,"text":"Keepalive di Upstream Load Balancer","type":"heading"},{"text":"Sama seperti di reverse proxy tunggal, `keepalive` di blok upstream adalah keharusan. Tanpa ini, NGINX membuka koneksi baru ke backend untuk setiap request — di 10.000 request per detik yang tersebar ke 3 server, itu 10.000 handshake per detik. Dengan `keepalive 32`, tiap worker memegang 32 koneksi idle per upstream. Satu detail penting: **total koneksi idle = keepalive × jumlah worker**. Dengan 4 worker dan `keepalive 32`, ada sampai 128 koneksi idle ke backend — pastikan `worker_connections` di backend cukup menampungnya.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/app.conf\nupstream app_backend {\n    least_conn;\n    server 10.0.0.11:3000;\n    server 10.0.0.12:3000;\n    keepalive 32;\n    keepalive_timeout 60s;\n    keepalive_requests 10000;\n}\n\nserver {\n    location / {\n        proxy_pass http://app_backend;\n        proxy_http_version 1.1;\n        proxy_set_header Connection \"\";\n        proxy_next_upstream error timeout http_502 http_503;\n        proxy_next_upstream_tries 3;\n    }\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"level":2,"text":"Sticky Session: ip_hash vs Cookie","type":"heading"},{"text":"Kalau aplikasimu menyimpan session di memory (bukan Redis), pengguna harus selalu sampai ke server yang sama — inilah **sticky session**. Di NGINX open source, caranya `ip_hash`. Kelemahannya: satu IP bisa mewakili banyak pengguna (kantor di belakang satu NAT, atau pengguna seluler yang IP-nya berubah-ubah), sehingga beban tidak merata — satu server bisa kebanjiran sementara server lain menganggur. NGINX Plus punya `sticky cookie` yang menempelkan cookie ke pengguna, jauh lebih akurat. Kalau kamu masih di open source dan butuh sticky yang lebih baik dari `ip_hash`, alternatifnya `hash $cookie_sessionid consistent` — routing berdasarkan cookie session aplikasi, bukan IP.","type":"paragraph"},{"code":"# Sticky berdasarkan cookie session aplikasi (NGINX open source)\nupstream app_backend {\n    hash $cookie_sessionid consistent;\n    server 10.0.0.11:3000;\n    server 10.0.0.12:3000;\n}\n\n# NGINX Plus: sticky cookie bawaan (lebih akurat)\n# upstream app_backend {\n#     server 10.0.0.11:3000;\n#     server 10.0.0.12:3000;\n#     sticky cookie srv_id expires=1h path=/;\n# }","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"kind":"tip","text":"Aturan emas: **simpan session di Redis, bukan di memory server**. Begitu session terpusat, kamu tidak butuh sticky session sama sekali — pakai `least_conn` dan server mana pun bisa melayani siapa pun. Ini juga membuat scale out menjadi sepele: tambah server baru, masukkan ke blok upstream, reload, selesai.","title":"Solusi jangka panjang: session terpusat","type":"callout"},{"level":2,"text":"Kapan Butuh Load Balancer?","type":"heading"},{"text":"Jangan menambah load balancer sebelum perlu — ia menambah satu hop network (latency +1–3 ms) dan satu titik yang harus dirawat. Tambahkan load balancer saat salah satu dari ini terjadi: satu server CPU-nya konsisten di atas **70%** di jam sibuk, kamu butuh deploy tanpa downtime, atau satu server mati berarti layanan mati total. Untuk permulaan, dua server backend + satu NGINX load balancer sudah memberikan ketahanan dan kapasitas hampir dua kali lipat. Dan ingat: load balancer itu sendiri bisa menjadi single point of failure — di setup serius, jalankan dua NGINX load balancer dengan IP virtual (keepalived/VRRP) supaya kalau satu mati, yang lain mengambil alih dalam hitungan detik.","type":"paragraph"},{"code":"# Uji beban seimbang dengan curl: 30 request, lihat header backend\nfor i in $(seq 1 30); do\n  curl -s -I https://api.contoh.id/health | grep -i \"x-served-by\"\ndone | sort | uniq -c\n\n# Contoh output (round-robin rata):\n#  10 x-served-by: srv-11\n#  10 x-served-by: srv-12\n#  10 x-served-by: srv-13\n\n# Catatan: tambahkan header ini di backend (mis. Node/Go)\n# supaya distribusi beban bisa diverifikasi dari luar.","filename":"terminal","language":"bash","type":"code"},{"items":["Mulai dengan round-robin; pindah ke `least_conn` kalau durasi request bervariasi.","Pakai `weight` untuk server dengan spesifikasi berbeda.","Pasang `max_fails=3 fail_timeout=30s` dan satu server `backup` untuk ketahanan.","Wajib: `keepalive` di upstream + HTTP/1.1 ke backend.","Simpan session di Redis supaya tidak butuh sticky session."],"ordered":true,"type":"list"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi yang dipakai di artikel ini: [NGINX Load Balancing — metode & upstream](https://nginx.org/en/docs/http/load_balancing.html), [NGINX Upstream Module — weight, max_fails, backup, keepalive](https://nginx.org/en/docs/http/ngx_http_upstream_module.html), dan [NGINX Proxy Module — proxy_next_upstream](https://nginx.org/en/docs/http/ngx_http_proxy_module.html).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-overview', 'Tuning NGINX untuk Performa: Gambaran Umum', 'Peta jalan tuning NGINX: dari cache sampai load balancing — mana yang paling berdampak untuk servermu', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80', 'Ruang server', 'NGINX', 'Pemula', '["nginx","performa","tuning","web-server"]', 'Deni', '2026-11-13', '2026-11-13', NULL, 1, '["nginx-cache","nginx-worker-tuning","nginx-rate-limit"]', 'NGINX Documentation', 'https://nginx.org/en/docs/', '[{"level":2,"text":"Kenapa NGINX Bisa Lambat?","type":"heading"},{"text":"NGINX terkenal cepat karena arsitekturnya yang **event-driven**: satu worker process bisa melayani ribuan koneksi bersamaan tanpa membuat thread baru untuk setiap request. Tapi cepat di atas kertas tidak otomatis berarti cepat di servermu. Dalam praktik, NGINX yang lambat hampir selalu disebabkan oleh empat hal: server membaca file dari disk berulang kali untuk konten yang sama, upstream seperti PHP atau aplikasi Node.js merespons dengan lambat, jumlah koneksi bersamaan melebihi kapasitas worker, atau tidak ada cache sama sekali sehingga setiap request menembus sampai ke backend. Kabar baiknya, keempat penyebab ini bisa diperbaiki dari sisi konfigurasi — tanpa menambah server baru dan tanpa mengubah kode aplikasi.","type":"paragraph"},{"items":["**Disk I/O berulang:** file statis seperti gambar, CSS, dan JavaScript dibaca dari disk setiap ada request, padahal isinya tidak berubah. Solusinya: cache di memori dan `sendfile`.","**Upstream lambat:** PHP-FPM atau aplikasi backend butuh 200–500 ms untuk menghasilkan satu halaman, lalu NGINX hanya meneruskannya. Solusinya: cache hasil upstream selama masih valid.","**Koneksi habis:** `worker_connections` bawaan terlalu kecil untuk traffic puncak, sehingga request baru antre atau ditolak. Solusinya: naikkan worker dan koneksi sesuai RAM dan CPU.","**Tanpa cache dan kompresi:** setiap byte dikirim mentah dan setiap request dihitung ulang. Solusinya: `proxy_cache` dan kompresi gzip atau Brotli."],"ordered":false,"type":"list"},{"level":2,"text":"Ukur Dulu, Tuning Kemudian","type":"heading"},{"text":"Aturan pertama tuning performa adalah **jangan menebak**. Sebelum mengubah satu baris konfigurasi pun, ukur dulu kondisi server saat ini: berapa request per detik yang mampu dilayani, berapa lama waktu respons rata-rata, dan di mana bottleneck-nya. Tanpa angka baseline, kamu tidak akan tahu apakah perubahanmu membantu atau justru memperburuk keadaan. Dua alat paling sederhana untuk ini adalah `ab` (ApacheBench) untuk uji beban dan `curl` untuk mengukur waktu respons satu request. Selain itu, aktifkan modul `stub_status` di NGINX supaya kamu bisa melihat jumlah koneksi aktif, request yang sedang diproses, dan koneksi yang menunggu — semuanya dari satu endpoint HTTP.","type":"paragraph"},{"code":"# Uji beban: 1000 request, 50 request bersamaan\nab -n 1000 -c 50 https://contoh.com/\n\n# Ukur waktu respons satu request (DNS, connect, TTFB, total)\ncurl -o /dev/null -s -w ''DNS:%{time_namelookup} Connect:%{time_connect} TTFB:%{time_starttransfer} Total:%{time_total}\\n'' https://contoh.com/\n\n# Lihat status koneksi NGINX secara langsung\ncurl http://127.0.0.1/nginx_status","filename":"benchmark.sh","language":"bash","type":"code"},{"code":"# Aktifkan stub_status (hanya dari localhost)\nserver {\n    listen 127.0.0.1:80;\n    server_name localhost;\n\n    location /nginx_status {\n        stub_status;\n        allow 127.0.0.1;\n        deny all;\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"kind":"tip","text":"Sebagai patokan awal: halaman statis sebaiknya merespons di bawah 50 ms (TTFB), halaman dinamis yang sudah di-cache di bawah 100 ms, dan halaman dinamis tanpa cache di bawah 300 ms. Kalau TTFB-mu di atas 500 ms untuk halaman yang sering dibuka, hampir pasti ada yang bisa diperbaiki — biasanya cache atau upstream. Catat angka baseline ini sebelum tuning, lalu bandingkan lagi setelah setiap perubahan.","title":"Angka Baseline yang Sehat","type":"callout"},{"level":2,"text":"4 Pilar Tuning NGINX","type":"heading"},{"text":"Semua teknik tuning NGINX bisa dikelompokkan ke dalam empat pilar. Urutannya di tabel bawah ini disusun berdasarkan **dampak per usaha**: cache dan kompresi biasanya memberi hasil terbesar dengan perubahan paling sedikit, sementara proteksi lebih ke arah stabilitas daripada kecepatan mentah.","type":"paragraph"},{"headers":["Pilar","Teknik utama","Perkiraan dampak","Usaha"],"rows":[["Cache","proxy_cache, fastcgi_cache","Beban upstream turun 70–90%, TTFB ke <50 ms","Rendah"],["Kompresi","gzip, Brotli","Ukuran transfer turun 70–80%","Rendah"],["Worker & koneksi","worker_processes, worker_connections, keepalive","Throughput naik 2–5x di traffic puncak","Sedang"],["Proteksi","limit_req, limit_conn","Server tetap responsif saat traffic abnormal","Sedang"]],"type":"table"},{"level":3,"text":"1. Cache: Jangan Hitung Ulang yang Sama","type":"heading"},{"text":"Cache adalah teknik dengan dampak terbesar untuk kebanyakan website. Ketika NGINX menyimpan salinan respons di memori atau disk, request berikutnya untuk URL yang sama dijawab langsung tanpa menyentuh backend sama sekali. Untuk halaman yang sering dibuka — beranda, halaman produk populer, atau API yang datanya jarang berubah — ini bisa memangkas beban upstream sampai **90%** dan membuat waktu respons turun dari ratusan milidetik menjadi belasan milidetik. Kuncinya adalah menentukan apa yang boleh di-cache, berapa lama, dan kapan cache harus dibersihkan.","type":"paragraph"},{"level":3,"text":"2. Kompresi: Kirim Lebih Sedikit, Sampai Lebih Cepat","type":"heading"},{"text":"File teks seperti HTML, CSS, dan JavaScript sangat bisa dikompresi: gzip biasanya memangkas ukurannya **70–80%**, dan Brotli bisa lebih kecil lagi sekitar 15–20% dibanding gzip. Untuk pengguna dengan koneksi lambat, ini perbedaan antara halaman yang terasa instan dan halaman yang terasa berat. Biaya yang dibayar adalah CPU untuk mengompresi — tapi dengan level kompresi 5 atau 6, biayanya kecil dan hampir selalu sepadan. Untuk file yang tidak berubah, kamu bahkan bisa mengompresi sekali di depan (`gzip_static`) supaya NGINX tidak perlu mengompresi berulang kali.","type":"paragraph"},{"level":3,"text":"3. Worker & Koneksi: Sesuaikan dengan Hardware","type":"heading"},{"text":"Nilai bawaan NGINX — satu worker process dan 512 koneksi per worker — dibuat konservatif supaya aman di server kecil. Di server dengan 4 core CPU dan traffic ribuan request per detik, nilai itu terlalu kecil: request antre, koneksi ditolak, dan latency melonjak. Aturan praktisnya: set `worker_processes` ke `auto` (satu worker per core CPU), naikkan `worker_connections` ke 2048 atau 4096, dan aktifkan `keepalive` ke upstream supaya koneksi ke backend dipakai ulang, bukan dibuka-tutup setiap request. Satu detail yang sering terlewat: setiap koneksi terbuka memakai satu file descriptor, jadi naikkan juga limit file descriptor sistem operasi.","type":"paragraph"},{"type":"code","language":"nginx","filename":"nginx.conf","code":"# Sesuaikan dengan jumlah core CPU (cek dengan: nproc)\nworker_processes auto;\nworker_rlimit_nofile 65535;\n\nevents {\n    worker_connections 4096;\n    use epoll;\n    multi_accept on;\n}\n\nhttp {\n    # Pakai ulang koneksi ke upstream, jangan buka-tutup tiap request\n    upstream backend {\n        server 127.0.0.1:8080;\n        keepalive 32;\n    }\n}"},{"level":3,"text":"4. Proteksi: Cepat untuk yang Normal, Ketat untuk yang Abnormal","type":"heading"},{"text":"Server yang cepat tapi roboh saat diserang bot atau traffic mendadak sama saja dengan server yang lambat. Rate limiting (`limit_req` dan `limit_conn`) memastikan satu IP atau satu client tidak bisa memonopoli server: request normal tetap dilayani dengan cepat, sementara request berlebihan ditahan atau ditolak dengan kode 503. Proteksi yang baik tidak terasa oleh pengguna normal — mereka tidak pernah menyentuh batasnya — tapi menyelamatkan server saat ada scraper agresif, percobaan brute force ke halaman login, atau lonjakan traffic yang tidak terduga.","type":"paragraph"},{"type":"code","language":"nginx","filename":"nginx.conf","code":"# Starter pack: cache + kompresi dalam satu location\nlocation / {\n    proxy_cache app_cache;\n    proxy_cache_valid 200 10m;\n    proxy_pass http://backend;\n}\n\n# Kompresi untuk semua respons teks\ngzip on;\ngzip_comp_level 6;\ngzip_types text/plain text/css application/javascript application/json;"},{"kind":"warning","text":"Setiap perubahan konfigurasi harus diuji satu per satu dan diukur dampaknya. Mengubah lima hal sekaligus lalu berharap performa membaik adalah cara tercepat untuk tidak tahu mana yang berhasil dan mana yang merusak. Ubah satu hal, uji beban lagi, bandingkan dengan baseline, lalu lanjut ke perubahan berikutnya. Dan selalu simpan salinan konfigurasi lama sebelum mengedit — `nginx -t` untuk memeriksa sintaks, baru `nginx -s reload` untuk menerapkan.","title":"Jangan Tuning Buta","type":"callout"},{"level":2,"text":"Urutan yang Direkomendasikan","type":"heading"},{"items":["Ukur baseline: catat request per detik, TTFB, dan jumlah koneksi aktif saat traffic normal dan puncak.","Aktifkan cache untuk konten yang sering diminta — ini biasanya memberi lonjakan performa terbesar.","Aktifkan kompresi gzip (dan Brotli bila memungkinkan) untuk semua respons teks.","Sesuaikan worker_processes, worker_connections, dan keepalive dengan jumlah core CPU dan RAM server.","Pasang rate limit di endpoint sensitif (login, API, pencarian) supaya server tetap stabil saat traffic abnormal."],"ordered":true,"type":"list"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi adalah sumber paling akurat untuk setiap directive yang dibahas di artikel ini: [NGINX Documentation](https://nginx.org/en/docs/). Artikel-artikel berikutnya di wiki ini membahas masing-masing pilar secara mendalam, lengkap dengan konfigurasi siap pakai.","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-rate-limit', 'Rate Limit di NGINX: limit_req & limit_conn', 'Lindungi server dari traffic abnormal: batasi request per detik dan koneksi bersamaan tanpa mematikan user normal', 'https://images.unsplash.com/photo-1629654297299-c8506221ca97?auto=format&fit=crop&w=1200&q=80', 'Terminal Linux', 'NGINX', 'Menengah', '["nginx","rate-limit","keamanan","ddos"]', 'Deni', '2026-11-13', '2026-11-13', 'nginx-overview', 2, '["nginx-overview","nginx-worker-tuning","linux-tuning"]', 'NGINX Rate Limiting', 'https://nginx.org/en/docs/http/ngx_http_limit_req_module.html', '[{"level":2,"text":"Kenapa Rate Limit Penting","type":"heading"},{"text":"Server yang cepat tetap bisa lumpuh dalam hitungan detik kalau satu client mengirim ribuan request sekaligus — entah itu bot scraper yang rakus, percobaan brute force ke halaman login, atau sekadar pengguna yang me-refresh halaman berkali-kali. Tanpa batasan, satu IP bisa memonopoli seluruh worker NGINX dan seluruh koneksi database, sehingga pengguna normal ikut tidak bisa mengakses. Rate limiting adalah pembatas kecepatan di jalan tol: semua orang tetap boleh lewat, tapi tidak ada yang boleh melaju 200 km/jam dan membahayakan pengguna lain. NGINX menyediakan dua alat untuk ini: `limit_req` untuk membatasi **jumlah request per detik**, dan `limit_conn` untuk membatasi **jumlah koneksi bersamaan**. Keduanya murah — hanya memakai sedikit memori per IP — dan bekerja sebelum request sampai ke aplikasi, jadi backend-mu tidak ikut terbebani.","type":"paragraph"},{"code":"http {\n    # Zona 10 MB (~160 ribu IP), batas 10 request/detik per IP\n    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;\n\n    server {\n        listen 80;\n        server_name contoh.com;\n\n        location /api/ {\n            limit_req zone=api_limit burst=20 nodelay;\n            proxy_pass http://127.0.0.1:8080;\n        }\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Memahami rate, burst, dan nodelay","type":"heading"},{"text":"Tiga parameter `limit_req` sering disalahpahami, padahal cara kerjanya sederhana. `rate` adalah kecepatan rata-rata yang diizinkan — misalnya `10r/s` berarti 10 request per detik per IP, atau `1r/m` untuk endpoint yang sangat sensitif seperti reset password. `burst` adalah toleransi untuk lonjakan sesaat: dengan `burst=20`, client boleh mengirim 20 request sekaligus melebihi rate, dan NGINX akan melayani mereka dengan sedikit penundaan (satu per 100 ms pada rate 10r/s) supaya tidak langsung ditolak. Tanpa `nodelay`, request dalam burst diproses perlahan sesuai rate — aman, tapi pengguna merasakan jeda. Dengan `nodelay`, 20 request pertama langsung diproses tanpa penundaan, dan request ke-21 langsung ditolak dengan kode **503**. Untuk API dan halaman biasa, `burst=20 nodelay` adalah kombinasi yang paling ramah: lonjakan normal lolos tanpa jeda, serangan yang terus-menerus langsung diblokir.","type":"paragraph"},{"headers":["Parameter","Arti","Contoh nilai"],"rows":[["rate","Kecepatan rata-rata yang diizinkan","10r/s, 1r/s, 5r/m"],["burst","Toleransi lonjakan sesaat (dijeda)","20"],["nodelay","Proses burst tanpa penundaan","nodelay"],["limit_req_status","Kode saat limit kena (default 503)","429"]],"type":"table"},{"level":2,"text":"Membatasi Koneksi Bersamaan dengan limit_conn","type":"heading"},{"text":"Rate limit menghitung request, tapi ada serangan yang tidak banyak mengirim request — melainkan membuka banyak koneksi dan menahannya tetap terbuka (slowloris adalah contoh klasik). Di sinilah `limit_conn` berperan: ia membatasi berapa koneksi TCP bersamaan yang boleh dibuka satu IP. Nilai yang wajar untuk website biasa adalah **10–20 koneksi per IP**, karena browser modern membuka sekitar 6 koneksi bersamaan per domain. Untuk endpoint download file, batasnya perlu lebih longgar atau dipisahkan zonanya, karena satu pengguna yang mengunduh file besar sambil membuka beberapa tab bisa dengan mudah melewati 10 koneksi. Sama seperti `limit_req`, zona didefinisikan sekali di blok `http` lalu dipakai di location yang diinginkan.","type":"paragraph"},{"code":"http {\n    # Maks 10 koneksi bersamaan per IP\n    limit_conn_zone $binary_remote_addr zone=conn_limit:10m;\n\n    server {\n        location / {\n            limit_conn conn_limit 10;\n            proxy_pass http://127.0.0.1:8080;\n        }\n\n        # Download file boleh lebih banyak koneksi\n        location /download/ {\n            limit_conn conn_limit 50;\n            proxy_pass http://127.0.0.1:8080;\n        }\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Limit per API Key, Bukan per IP","type":"heading"},{"text":"Membatasi per IP bermasalah saat banyak pengguna berada di balik satu NAT — misalnya satu kantor atau satu kampus yang keluar lewat satu IP publik. Semua pengguna itu akan berbagi satu kuota dan saling memblokir. Solusinya adalah membatasi berdasarkan **API key** atau token pengguna, bukan alamat IP. Caranya: buat variabel dengan `map` yang membaca header `X-Api-Key` atau Authorization, lalu jadikan variabel itu kunci zona. Pengguna tanpa API key tetap dibatasi per IP sebagai fallback. Pendekatan yang sama bisa dipakai untuk membedakan paket pengguna: paket gratis mendapat `1r/s`, paket berbayar `100r/s` — cukup dengan dua zona dan dua `map` yang berbeda.","type":"paragraph"},{"code":"http {\n    # Kunci zona = API key bila ada, kalau tidak pakai IP\n    map $http_x_api_key $limit_key {\n        default $binary_remote_addr;\n        ~.+ $http_x_api_key;\n    }\n\n    limit_req_zone $limit_key zone=key_limit:10m rate=30r/s;\n\n    server {\n        location /api/v1/ {\n            limit_req zone=key_limit burst=30 nodelay;\n            proxy_pass http://127.0.0.1:8080;\n        }\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Saat Limit Kena: Kode 503 dan Log","type":"heading"},{"text":"Secara bawaan, request yang melewati batas ditolak dengan kode **503 Service Temporarily Unavailable** — kode yang memberitahu client (dan search engine) untuk mencoba lagi nanti, bukan bahwa halaman tidak ada. Kamu bisa mengubahnya menjadi **429 Too Many Requests** dengan directive `limit_req_status 429`, yang lebih semantik untuk API. Yang tidak kalah penting adalah log: setiap penolakan dicatat di error log dengan pesan `limiting requests` atau `limiting connections` beserta IP pelakunya. Log ini adalah sumber informasi terbaikmu — dari sanalah kamu tahu apakah yang kena limit adalah bot penyerang atau justru pengguna normal yang batasnya terlalu ketat. Kalau kamu melihat IP yang sama kena limit ribuan kali per jam, itu kandidat untuk diblokir permanen di firewall; kalau yang kena limit adalah IP kantor sendiri, batasmu yang perlu dilonggarkan.","type":"paragraph"},{"code":"http {\n    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;\n    limit_req_status 429;\n\n    server {\n        location /api/ {\n            limit_req zone=api_limit burst=20 nodelay;\n            # Halaman error khusus untuk yang kena limit\n            error_page 429 /rate-limited.html;\n            proxy_pass http://127.0.0.1:8080;\n        }\n\n        location = /rate-limited.html {\n            internal;\n            root /var/www/contoh.com/errors;\n        }\n    }\n}\n\n# Cek siapa saja yang kena limit hari ini\n# grep ''limiting requests'' /var/log/nginx/error.log | awk ''{print $7}'' | sort | uniq -c | sort -rn | head","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Contoh: Proteksi Login dan API","type":"heading"},{"text":"Dua endpoint paling membutuhkan rate limit adalah **login** dan **API publik**. Halaman login adalah target brute force: tanpa batasan, penyerang bisa mencoba ribuan kombinasi password per menit. Batas yang wajar adalah **1 request per detik dengan burst 5** — manusia yang salah ketik password tiga kali tidak akan merasakan apa-apa, tapi bot yang mencoba 100 password per detik langsung terpotong. Untuk API publik, batasnya tergantung paket: **10r/s untuk umum** sudah cukup untuk aplikasi yang wajar, dan endpoint pencarian — yang biasanya menjalankan query database berat — sebaiknya dibatasi lebih ketat lagi, misalnya 2r/s, karena satu query pencarian bisa semahal puluhan query biasa.","type":"paragraph"},{"code":"http {\n    limit_req_zone $binary_remote_addr zone=login_limit:10m rate=1r/s;\n    limit_req_zone $binary_remote_addr zone=search_limit:10m rate=2r/s;\n    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;\n\n    server {\n        # Login: sangat ketat, brute force langsung mentok\n        location = /login {\n            limit_req zone=login_limit burst=5 nodelay;\n            proxy_pass http://127.0.0.1:8080;\n        }\n\n        # Pencarian: query berat, batasi lebih ketat\n        location /search {\n            limit_req zone=search_limit burst=5 nodelay;\n            proxy_pass http://127.0.0.1:8080;\n        }\n\n        # API umum\n        location /api/ {\n            limit_req zone=api_limit burst=20 nodelay;\n            proxy_pass http://127.0.0.1:8080;\n        }\n    }\n}","filename":"nginx.conf","language":"nginx","type":"code"},{"kind":"warning","text":"Rate limit yang terlalu ketat lebih merusak daripada tidak ada rate limit. Bayangkan pengguna normal yang membuka halaman lalu browser-nya memuat 30 aset sekaligus — kalau batasmu 5 request per detik tanpa burst, halaman itu akan gagal dimuat sebagian dan pengguna mengira websitemu rusak. Selalu beri `burst` yang cukup (minimal 10–20) dan pantau error log selama seminggu pertama. Kalau IP kantor atau IP monitoring-mu sendiri kena limit, masukkan mereka ke whitelist dengan `geo` sebelum batas diterapkan.","title":"Jangan Terlalu Ketat","type":"callout"},{"kind":"tip","text":"Untuk memutihkan IP internal, load balancer, atau layanan monitoring, gunakan blok `geo` yang menghasilkan variabel 0 atau 1, lalu jadikan bagian dari kunci zona: IP yang bernilai 0 mendapat kunci kosong dan tidak dihitung limitnya. Dengan begitu, health check dari load balancer tidak akan pernah kena rate limit dan memicu alarm yang tidak perlu.","title":"Whitelist IP Internal","type":"callout"},{"code":"# IP internal & monitoring tidak kena limit\ngeo $is_internal {\n    default 1;\n    10.0.0.0/8 0;\n    192.168.0.0/16 0;\n    203.0.113.10 0; # IP monitoring\n}\n\n# Kunci kosong ('''') berarti request tidak dihitung limitnya\nmap $is_internal $limit_key {\n    0 '''';\n    default $binary_remote_addr;\n}\n\nlimit_req_zone $limit_key zone=api_limit:10m rate=10r/s;","filename":"nginx.conf","language":"nginx","type":"code"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi modul rate limiting NGINX: [NGINX Rate Limiting](https://nginx.org/en/docs/http/ngx_http_limit_req_module.html). Modul limit koneksi didokumentasikan di halaman yang sama untuk `ngx_http_limit_conn_module`.","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-reverse-proxy-tuning', 'Tuning Reverse Proxy NGINX', 'Proxy yang cepat: buffering, timeout, dan keepalive ke upstream — jangan biarkan proxy jadi bottleneck', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80', 'Dashboard monitoring', 'NGINX', 'Menengah', '["nginx","reverse-proxy","upstream","buffering"]', 'Deni', '2026-11-13', '2026-11-13', 'nginx-worker-tuning', 1, '["nginx-worker-tuning","nginx-load-balancing","nginx-cache"]', 'NGINX Proxy Module', 'https://nginx.org/en/docs/http/ngx_http_proxy_module.html', '[{"text":"Reverse proxy adalah posisi paling strategis sekaligus paling rawan di arsitektur web: **semua** request melewatinya sebelum sampai ke aplikasi. Proxy yang tidak di-tuning akan jadi bottleneck — backend yang sebenarnya sanggup menjawab 5.000 request per detik bisa terlihat lambat hanya karena NGINX menunggu timeout terlalu lama, membuka koneksi baru ke backend untuk setiap request, atau menahan response di buffer yang terlalu kecil. Artikel ini membahas empat tuas utama: buffering, timeout, keepalive ke upstream, dan failover.","type":"paragraph"},{"kind":"info","text":"Tanpa keepalive ke upstream, NGINX membuka **satu koneksi TCP baru untuk setiap request** ke backend — plus handshake TLS kalau backend memakai HTTPS. Di 1.000 request per detik, itu 1.000 handshake per detik yang membuang CPU dan menambah latency **5–15 ms per request**. Dengan `keepalive` di blok upstream, koneksi dipakai ulang dan latency tambahan itu hilang.","title":"Satu angka yang paling berpengaruh","type":"callout"},{"level":2,"text":"proxy_buffering dan Ukuran Buffer","type":"heading"},{"text":"Saat backend mengirim response, NGINX tidak langsung meneruskannya ke klien begitu saja. Dengan `proxy_buffering on` (default), NGINX menampung response di buffer dulu, lalu mengirimkannya ke klien secepat klien mampu menerima. Manfaatnya besar: **backend bebas lebih cepat**. Begitu response masuk buffer NGINX, worker backend (mis. PHP-FPM atau Node) bisa langsung menangani request berikutnya, tanpa menunggu klien lambat selesai download. Tanpa buffering, satu klien dengan koneksi 1 Mbps bisa menahan satu worker backend selama puluhan detik.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/app.conf\nlocation / {\n    proxy_pass http://app_backend;\n\n    # Buffering: tampung response backend dulu, lalu kirim ke klien\n    proxy_buffering      on;\n    proxy_buffer_size    8k;     # buffer pertama (header response)\n    proxy_buffers        8 16k;  # 8 buffer x 16 KB = 128 KB untuk body\n    proxy_busy_buffers_size 32k; # maks buffer yang boleh dikirim sekaligus\n    proxy_max_temp_file_size 0;  # jangan tulis response ke disk (hindari I/O)\n\n    # Request body dari klien: buffer di memory, jangan stream mentah\n    client_body_buffer_size 128k;\n    client_max_body_size    20m;\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"text":"Aturan ukurannya: `proxy_buffers` harus cukup menampung response yang umum. Kalau response API-mu rata-rata 20 KB, `8 16k` (128 KB) sudah longgar. Kalau response sering 500 KB (mis. laporan JSON besar), naikkan ke `16 16k` atau matikan buffering untuk location itu (`proxy_buffering off`) — tapi ingat, mematikan buffering berarti backend menanggung klien lambat secara langsung. `proxy_max_temp_file_size 0` penting di server dengan disk lambat: tanpa ini, response yang lebih besar dari buffer ditulis ke file sementara di disk, dan I/O disk jadi bottleneck baru.","type":"paragraph"},{"level":2,"text":"Timeout: Jangan Biarkan Request Menggantung","type":"heading"},{"text":"Nilai default timeout NGINX adalah **60 detik** untuk hampir semuanya — terlalu lama untuk API modern. Bayangkan backend mengalami deadlock dan setiap request menunggu 60 detik: dengan 200 worker, 200 request sudah cukup untuk melumpuhkan seluruh server selama satu menit penuh. Timeout yang ketat membuat kegagalan terdeteksi cepat dan slot worker cepat bebas lagi.","type":"paragraph"},{"headers":["Directive","Default","Rekomendasi","Alasan"],"rows":[["`proxy_connect_timeout`","60s","5s","Backend down harus ketahuan dalam 5 detik, bukan 60 detik"],["`proxy_read_timeout`","60s","30s","API normal selesai < 5 detik; 30 detik cukup untuk query berat"],["`proxy_send_timeout`","60s","30s","Kirim request body ke backend tidak boleh menggantung"],["`client_body_timeout`","60s","10s","Klien lambat upload tidak boleh menahan worker"],["`send_timeout`","60s","30s","Kirim response ke klien dibatasi, putuskan klien macet"]],"type":"table"},{"code":"# /etc/nginx/conf.d/app.conf\nlocation / {\n    proxy_pass http://app_backend;\n\n    proxy_connect_timeout 5s;   # gagal cepat kalau backend tidak merespons\n    proxy_read_timeout    30s;  # tunggu response backend maks 30 detik\n    proxy_send_timeout    30s;\n    client_body_timeout   10s;\n    send_timeout          30s;\n\n    # Endpoint khusus yang memang lama (export laporan, dsb.)\n    # taruh di location terpisah dengan timeout lebih longgar:\n}\n\nlocation /api/export {\n    proxy_pass http://app_backend;\n    proxy_read_timeout 300s;  # export boleh lama, tapi hanya di endpoint ini\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"kind":"warning","text":"Jangan samakan timeout `location /` dengan endpoint long-polling atau SSE (Server-Sent Events). Endpoint seperti itu **sengaja** menahan koneksi berjam-jam — beri mereka `location` sendiri dengan `proxy_read_timeout 3600s` dan `proxy_buffering off`, supaya timeout ketat di location utama tidak memutus koneksi yang sah.","title":"Timeout ketat, kecuali untuk long-polling","type":"callout"},{"level":2,"text":"Keepalive ke Upstream: Wajib untuk API","type":"heading"},{"text":"Ini kesalahan konfigurasi paling umum di reverse proxy NGINX: `proxy_pass` ditulis, tapi tidak ada `keepalive` di blok upstream. Akibatnya NGINX memakai HTTP/1.0 ke backend dan menutup koneksi setiap request. Tiga baris ini mengaktifkan keepalive: `keepalive 32` di upstream, `proxy_http_version 1.1`, dan `proxy_set_header Connection \"\"` (menghapus header `Connection: close` yang dikirim NGINX secara default). Efeknya langsung terasa: di benchmark internal, latency p99 turun dari **45 ms ke 28 ms** dan jumlah socket TIME_WAIT di backend berkurang lebih dari 90%.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/app.conf\nupstream app_backend {\n    server 127.0.0.1:3000;\n    server 127.0.0.1:3001;\n    keepalive 32;          # 32 koneksi idle per worker ke backend\n    keepalive_timeout 60s;\n    keepalive_requests 10000;\n}\n\nserver {\n    listen 443 ssl;\n    server_name api.contoh.id;\n\n    location / {\n        proxy_pass http://app_backend;\n        proxy_http_version 1.1;            # keepalive butuh HTTP/1.1\n        proxy_set_header Connection \"\";    # hapus \"Connection: close\"\n\n        proxy_set_header Host $host;\n        proxy_set_header X-Real-IP $remote_addr;\n        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n        proxy_set_header X-Forwarded-Proto $scheme;\n    }\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"text":"Angka `keepalive 32` berarti tiap worker NGINX memegang sampai 32 koneksi idle ke backend. Dengan 4 worker, totalnya 128 koneksi — cukup untuk traffic 5.000 request per detik. Header `X-Forwarded-For` dan `X-Real-IP` juga jangan lupa: tanpa ini, aplikasi backend melihat semua request berasal dari IP NGINX (127.0.0.1), sehingga rate limit, log, dan deteksi abuse di aplikasi menjadi tidak berguna. Di aplikasi, baca IP asli dari header tersebut — atau lebih aman, pakai modul `ngx_http_realip_module` dengan `set_real_ip_from` untuk IP proxy tepercaya.","type":"paragraph"},{"level":2,"text":"proxy_cache vs proxy_buffering","type":"heading"},{"text":"Keduanya menyimpan response, tapi tujuannya berbeda. **Buffering** hanya menampung response sesaat supaya backend cepat bebas — response tetap dihitung ulang setiap request. **Cache** (`proxy_cache`) menyimpan response dan melayani request berikutnya **tanpa menyentuh backend sama sekali**. Untuk endpoint yang jawabannya sama untuk semua orang (artikel, katalog produk, hasil pencarian populer), cache bisa memangkas beban backend **70–90%**. Bedanya dengan buffering: cache butuh `proxy_cache_path`, `proxy_cache_valid`, dan strategi invalidasi — topik ini dibahas lengkap di artikel [NGINX Cache](/nginx-cache).","type":"paragraph"},{"code":"# Cache HANYA untuk response yang aman di-cache (GET, status 200)\nproxy_cache_path /var/cache/nginx levels=1:2 keys_zone=api_cache:100m\n                 max_size=1g inactive=60m use_temp_path=off;\n\nlocation /api/public/ {\n    proxy_pass http://app_backend;\n    proxy_cache api_cache;\n    proxy_cache_valid 200 5m;   # cache response 200 selama 5 menit\n    proxy_cache_valid 404 1m;\n    proxy_cache_use_stale error timeout updating;  # sajikan cache lama saat backend down\n    add_header X-Cache-Status $upstream_cache_status;  # HIT / MISS / BYPASS\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"level":2,"text":"Failover dengan proxy_next_upstream","type":"heading"},{"text":"Kalau satu backend mati, NGINX tidak harus langsung mengembalikan `502` ke pengguna. Dengan `proxy_next_upstream`, request yang gagal akan dicoba ke server upstream berikutnya — pengguna tidak merasakan apa-apa kecuali latency bertambah sedikit. Ini failover pasif yang murah dan efektif, terutama kalau dikombinasikan dengan `max_fails` dan `fail_timeout` di blok upstream.","type":"paragraph"},{"code":"# /etc/nginx/conf.d/app.conf\nupstream app_backend {\n    server 10.0.0.11:3000 max_fails=3 fail_timeout=30s;\n    server 10.0.0.12:3000 max_fails=3 fail_timeout=30s;\n    server 10.0.0.13:3000 backup;  # hanya dipakai kalau dua server utama down\n    keepalive 32;\n}\n\nlocation / {\n    proxy_pass http://app_backend;\n    # Coba server lain kalau: error koneksi, timeout, atau 502/503\n    proxy_next_upstream error timeout http_502 http_503;\n    proxy_next_upstream_tries 3;      # maks 3 percobaan total\n    proxy_next_upstream_timeout 10s;  # total waktu failover maks 10 detik\n}","filename":"/etc/nginx/conf.d/app.conf","language":"nginx","type":"code"},{"text":"Perhatian: `proxy_next_upstream` hanya aman untuk request yang **idempotent** (GET, HEAD, dan request tanpa efek samping). Untuk POST yang mengubah data (mis. pembayaran), mengulang request ke server lain berisiko memproses transaksi **dua kali**. Karena itu NGINX secara default hanya mengulang request non-idempotent kalau ada `proxy_next_upstream` dengan kondisi `error` saja — dan kamu sebaiknya tidak menambahkan `http_500` atau `non_idempotent` untuk endpoint tulis.","type":"paragraph"},{"kind":"tip","text":"Setelah tuning, verifikasi dengan `curl -I https://api.contoh.id/api/public/x` dan lihat header `X-Cache-Status`: `HIT` berarti dilayani dari cache (latency < 5 ms), `MISS` berarti baru dihitung backend. Untuk mengukur keepalive, cek `ss -s` di backend: jumlah socket TIME_WAIT yang turun drastis setelah keepalive aktif adalah bukti konfigurasi bekerja.","title":"Cara cepat memverifikasi","type":"callout"},{"items":["Aktifkan `proxy_buffering` dengan buffer yang cukup untuk response terbesarmu.","Ketatkan timeout: connect 5 detik, read/send 30 detik; longgarkan hanya di endpoint khusus.","Wajib: `keepalive` di upstream + `proxy_http_version 1.1` + `Connection \"\"`.","Teruskan header `Host`, `X-Real-IP`, dan `X-Forwarded-For` ke backend.","Siapkan failover dengan `proxy_next_upstream` dan server `backup`."],"ordered":true,"type":"list"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi yang dipakai di artikel ini: [NGINX Proxy Module — proxy_buffering, proxy_cache & timeout](https://nginx.org/en/docs/http/ngx_http_proxy_module.html), [NGINX Upstream Module — keepalive & max_fails](https://nginx.org/en/docs/http/ngx_http_upstream_module.html), dan [NGINX Load Balancing — health check pasif](https://nginx.org/en/docs/http/load_balancing.html).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('nginx-worker-tuning', 'Worker, Koneksi & Keepalive di NGINX', 'Naikkan kapasitas concurrent: atur worker_processes, worker_connections, dan keepalive dengan benar', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80', 'Ruang server', 'NGINX', 'Menengah', '["nginx","worker","keepalive","concurrent"]', 'Deni', '2026-11-13', '2026-11-13', 'nginx-overview', 4, '["nginx-overview","nginx-reverse-proxy-tuning","linux-tuning"]', 'NGINX Documentation', 'https://nginx.org/en/docs/ngx_core_module.html', '[{"text":"Satu worker NGINX bisa melayani **ribuan koneksi bersamaan** — tapi hanya kalau tiga angka ini benar: jumlah worker, batas koneksi per worker, dan batas file descriptor sistem operasi. Salah satu saja terlalu kecil, server yang sebenarnya masih longgar akan mulai menolak koneksi dan mengembalikan `502` atau `connection refused`. Artikel ini membahas cara menghitung dan mengatur ketiganya, plus keepalive dan optimasi TCP, supaya satu server 4 core bisa menangani **10.000+ koneksi concurrent** dengan latency tetap di bawah 50 ms.","type":"paragraph"},{"kind":"info","text":"NGINX memakai model **event-driven non-blocking**: satu worker process menunggu banyak koneksi sekaligus dalam satu event loop, dan hanya bekerja saat ada event (data masuk, koneksi baru). Bandingkan dengan Apache `prefork` yang membuat satu thread per koneksi — di 10.000 koneksi, Apache butuh 10.000 thread dan memory-nya habis duluan. Karena itu NGINX hampir selalu menang di beban concurrent tinggi.","title":"Kenapa NGINX kuat di concurrent tinggi?","type":"callout"},{"level":2,"text":"worker_processes: Satu Worker per Core","type":"heading"},{"text":"Saat NGINX start, ia menjalankan satu **master process** dan sejumlah **worker process**. Master hanya membaca konfigurasi dan mengatur worker; worker-lah yang menerima koneksi dan menjawab request. Aturan praktisnya sederhana: **jumlah worker = jumlah CPU core**. Satu worker per core membuat setiap core sibuk tanpa rebutan CPU, dan tidak ada worker yang menganggur.","type":"paragraph"},{"code":"# /etc/nginx/nginx.conf — blok utama\nuser  www-data;\nworker_processes  auto;   # 1 worker per CPU core (4 core = 4 worker)\nworker_cpu_affinity auto; # pin tiap worker ke satu core (kurangi context switch)\npid        /run/nginx.pid;\nerror_log  /var/log/nginx/error.log warn;","filename":"/etc/nginx/nginx.conf","language":"nginx","type":"code"},{"text":"Nilai `auto` (NGINX 1.9.1+) otomatis memakai jumlah core, jadi konfigurasi yang sama bisa dipakai di server 2 core maupun 16 core tanpa diubah. Jangan menaikkan worker melebihi jumlah core — worker tambahan hanya berebut CPU yang sama dan menambah context switch, throughput justru turun **5–10%** pada benchmark `wrk`. Satu-satunya pengecualian: kalau worker sering menunggu disk (beban I/O berat), worker ekstra bisa membantu, tapi itu tanda kamu butuh `aio threads`, bukan worker lebih banyak.","type":"paragraph"},{"level":2,"text":"Rumus Kapasitas Concurrent","type":"heading"},{"text":"Kapasitas maksimum koneksi NGINX bisa dihitung dengan rumus sederhana: **worker_processes × worker_connections**. Dengan 4 core dan `worker_connections 4096`, kapasitas teoritisnya 4 × 4096 = **16.384 koneksi bersamaan**. Tapi ingat, ini batas atas: setiap koneksi ke upstream (reverse proxy) memakai 1 file descriptor tambahan, dan koneksi keepalive yang idle tetap memakan satu slot koneksi sampai timeout.","type":"paragraph"},{"headers":["Directive","Default","Rekomendasi","Dampak performa"],"rows":[["`worker_processes`","`1`","`auto`","Semua core terpakai, throughput naik ~4x di 4 core"],["`worker_connections`","`512`","`4096`–`8192`","Kapasitas concurrent naik dari ~2.000 ke ~16.000+"],["`worker_rlimit_nofile`","limit OS (1024)","`65535`","Worker tidak kehabisan file descriptor"],["`multi_accept`","`off`","`on`","Worker menerima semua koneksi antrean sekaligus"],["`keepalive_timeout`","`75s`","`65s`","Koneksi idle dilepas lebih cepat, slot bebas"]],"type":"table"},{"level":2,"text":"worker_connections dan Batas File Descriptor","type":"heading"},{"text":"Ini jebakan yang paling sering membuat NGINX tumbang di traffic tinggi: `worker_connections` boleh diset 8192, tapi sistem operasi membatasi file descriptor (FD) per process — biasanya hanya **1024** di instalasi default. Setiap koneksi klien memakai 1 FD, dan koneksi ke upstream memakai 1 FD lagi. Begitu FD habis, NGINX mencatat `accept() failed (24: Too many open files)` dan menolak koneksi baru meski CPU masih 20%. Solusinya dua lapis: naikkan limit di NGINX dan di sistem.","type":"paragraph"},{"code":"# 1. Cek limit saat ini (harus >= worker_connections x 2)\ncat /proc/$(cat /run/nginx.pid)/limits | grep \"open files\"\nulimit -n   # limit shell, biasanya 1024\n\n# 2. Naikkan limit di NGINX\n# /etc/nginx/nginx.conf, di dalam blok events:\n#   worker_rlimit_nofile 65535;\n\n# 3. Naikkan limit di systemd (NGINX dari paket distro memakai systemd)\n# /etc/systemd/system/nginx.service.d/limits.conf\n[Service]\nLimitNOFILE=65535\n\n# 4. Terapkan dan verifikasi\nsystemctl daemon-reload && systemctl restart nginx\ncat /proc/$(cat /run/nginx.pid)/limits | grep \"open files\"","filename":"terminal","language":"bash","type":"code"},{"kind":"warning","text":"Selalu pastikan `worker_rlimit_nofile` **lebih besar** dari `worker_connections`. Kalau `worker_connections 8192` tapi FD hanya 1024, NGINX tetap mentok di ~1000 koneksi per worker dan error log akan penuh dengan `too many open files`. Di reverse proxy, hitung kebutuhan FD sebagai `worker_connections × 2` karena tiap request memegang 1 FD klien + 1 FD upstream.","title":"FD habis = server menolak koneksi","type":"callout"},{"level":2,"text":"Keepalive: Hemat Handshake, Jaga Kapasitas","type":"heading"},{"text":"Tanpa keepalive, setiap request HTTP membuka koneksi TCP baru — lengkap dengan three-way handshake dan, untuk HTTPS, handshake TLS yang bisa memakan **2–3 round trip** tambahan (~50–100 ms di jaringan seluler). Dengan `keepalive_timeout 65s`, browser memakai ulang koneksi yang sama untuk puluhan request, latency per request turun drastis dan beban CPU untuk TLS berkurang. Di sisi lain, koneksi keepalive yang idle tetap memakan satu slot `worker_connections` — jadi jangan set timeout terlalu panjang di server API yang melayani ribuan klien berbeda.","type":"paragraph"},{"code":"# /etc/nginx/nginx.conf — blok http\nhttp {\n    keepalive_timeout  65s;    # tutup koneksi idle setelah 65 detik\n    keepalive_requests 1000;   # maks 1000 request per koneksi\n    reset_timedout_connection on;  # bebaskan socket dari klien yang sudah pergi\n\n    # Ke upstream (reverse proxy): pakai ulang koneksi ke backend\n    upstream app_backend {\n        server 127.0.0.1:3000;\n        keepalive 32;  # 32 koneksi idle per worker ke backend\n    }\n}","filename":"/etc/nginx/nginx.conf (http)","language":"nginx","type":"code"},{"text":"Angka `keepalive_requests 1000` adalah default sejak NGINX 1.19.10 dan sudah tepat untuk kebanyakan kasus. Kalau kamu melayani file besar lewat satu koneksi (download), angka ini tidak relevan — yang penting adalah `keepalive_timeout`. Untuk API dengan traffic tinggi dari sedikit klien (mis. 100 service internal), menaikkan `keepalive_requests` ke `10000` mengurangi churn koneksi dan menurunkan latency p99 sekitar **10–20%**.","type":"paragraph"},{"kind":"tip","text":"Untuk server yang melayani banyak klien berbeda (mis. API publik), pakai `keepalive_timeout 65s` dan jangan lebih. Untuk komunikasi internal antar service (NGINX ke backend), pakai `keepalive 32` di blok upstream — koneksi ke backend jadi dipakai ulang, dan kamu menghemat satu handshake TCP + TLS per request.","title":"Aturan praktis keepalive","type":"callout"},{"level":2,"text":"multi_accept, sendfile, dan Optimasi TCP","type":"heading"},{"text":"Tiga directive kecil di blok `events` dan `http` ini sering diabaikan, padahal dampaknya terasa saat traffic meledak. `multi_accept on` membuat worker menerima **semua** koneksi yang antre di listen socket dalam satu putaran event loop — tanpa ini, worker hanya menerima satu koneksi per putaran, dan antrean bisa menumpuk saat ada lonjakan 10.000 koneksi dalam satu detik. `sendfile on` memindahkan file statis langsung dari kernel ke socket tanpa melewati user-space (zero-copy), dan `tcp_nopush` + `tcp_nodelay` memastikan paket dikirim efisien: header dan isi dikirim bersamaan, tanpa menunggu ACK yang tidak perlu.","type":"paragraph"},{"code":"# /etc/nginx/nginx.conf\nevents {\n    worker_connections 4096;\n    use epoll;          # Linux: epoll jauh lebih cepat dari select()\n    multi_accept on;    # terima semua koneksi antrean sekaligus\n}\n\nhttp {\n    sendfile       on;  # zero-copy untuk file statis\n    tcp_nopush     on;  # kirim header + isi dalam satu paket\n    tcp_nodelay    on;  # jangan tunda paket kecil (penting untuk API)\n    server_tokens  off; # sembunyikan versi NGINX dari header\n}","filename":"/etc/nginx/nginx.conf (events & http)","language":"nginx","type":"code"},{"level":2,"text":"Mengukur: ab, wrk, dan stub_status","type":"heading"},{"text":"Jangan menebak — ukur. Sebelum dan sesudah tuning, jalankan benchmark yang sama dan bandingkan tiga angka: **requests per second**, **latency p99**, dan **failed requests**. `ab` (ApacheBench) sudah terpasang di kebanyakan distro, sedangkan `wrk` lebih akurat untuk concurrent tinggi karena memakai banyak thread. Modul `stub_status` memberi angka live: berapa koneksi aktif, berapa yang sedang membaca/menulis, dan berapa yang menunggu (waiting = koneksi keepalive idle).","type":"paragraph"},{"code":"# Benchmark: 10.000 request, 200 koneksi bersamaan\nab -n 10000 -c 200 -k https://api.contoh.id/health\n\n# wrk: 4 thread, 400 koneksi, selama 30 detik\nwrk -t4 -c400 -d30s --latency https://api.contoh.id/health\n\n# Aktifkan stub_status untuk monitoring live\n# /etc/nginx/conf.d/status.conf\nserver {\n    listen 127.0.0.1:8080;\n    location /nginx_status {\n        stub_status;\n        allow 127.0.0.1;\n        deny all;\n    }\n}\n\n# Contoh output stub_status:\n# Active connections: 1847\n# server accepts handled requests\n#  128034 128034 342110\n# Reading: 12 Writing: 96 Waiting: 1739","filename":"terminal","language":"bash","type":"code"},{"text":"Kalau angka `Waiting` mendominasi dan `Active connections` mendekati `worker_processes × worker_connections`, itu sinyal kapasitas sudah penuh — naikkan `worker_connections` dan FD, atau tambah server di belakang load balancer. Kalau `Writing` tinggi tapi CPU rendah, bottleneck-nya kemungkinan di upstream (backend lambat), bukan di NGINX. Selalu ubah **satu directive dalam satu waktu** dan ukur lagi, supaya kamu tahu perubahan mana yang benar-benar berpengaruh.","type":"paragraph"},{"items":["Cek core CPU dengan `nproc`, set `worker_processes auto` dan `worker_cpu_affinity auto`.","Set `worker_connections 4096`, lalu naikkan FD ke `65535` di NGINX dan systemd.","Aktifkan `multi_accept on`, `sendfile on`, `tcp_nopush on`, dan `tcp_nodelay on`.","Atur `keepalive_timeout 65s` dan `keepalive_requests 1000` untuk klien, plus `keepalive` ke upstream.","Ukur sebelum-sesudah dengan `wrk` dan pantau `stub_status` secara berkala."],"ordered":true,"type":"list"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi dan alat ukur yang dipakai di artikel ini: [NGINX Core Module — worker_processes & worker_rlimit_nofile](https://nginx.org/en/docs/ngx_core_module.html), [NGINX Events Module — worker_connections & multi_accept](https://nginx.org/en/docs/ngx_core_module.html), [NGINX ngx_http_core_module — keepalive_timeout](https://nginx.org/en/docs/http/ngx_http_core_module.html), dan [wrk — HTTP benchmarking tool](https://github.com/wg/wrk).","type":"paragraph"}]', '2026-11-13');
INSERT OR REPLACE INTO articles (slug, title, subtitle, image, image_alt, category, difficulty, tags, author, date_created, date_updated, parent, order_index, related, source_label, source_url, blocks, updated_at) VALUES ('redis-cache', 'Caching Aplikasi dengan Redis', 'Potong latency query dari milidetik ke mikrodetik: cache hasil query, session, dan halaman', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80', 'Dashboard monitoring', 'Download & Cache', 'Menengah', '["redis","cache","aplikasi"]', 'Deni', '2026-11-13', '2026-11-13', NULL, 2, '["nginx-cache","file-download","database-query"]', 'Redis Documentation', 'https://redis.io/docs/latest/', '[{"level":2,"text":"Kenapa Cache Mengubah Segalanya","type":"heading"},{"text":"Setiap request yang masuk ke aplikasi hampir selalu berakhir di database. Satu query sederhana ke PostgreSQL atau MySQL umumnya memakan waktu 5 sampai 50 milidetik, dan query yang melibatkan join beberapa tabel besar bisa menembus 200 milidetik atau lebih. Kalau satu halaman membutuhkan 10 query, total waktunya dengan mudah mencapai setengah detik hanya untuk menunggu database. Di sinilah Redis masuk: Redis menyimpan data di memori (RAM), bukan di disk, sehingga satu operasi baca biasanya selesai dalam 0,1 sampai 1 milidetik. Itu berarti 10 sampai 100 kali lebih cepat daripada query database biasa, dan satu instance Redis kecil sanggup melayani lebih dari 100.000 operasi per detik.","type":"paragraph"},{"text":"Cache bukan sulap yang membuat semua query jadi cepat. Cache hanya efektif untuk data yang sering dibaca tetapi jarang berubah. Contoh yang ideal adalah katalog produk, daftar kategori, konfigurasi aplikasi, hasil agregasi harian, dan profil pengguna. Sebaliknya, jangan meng-cache data yang berubah setiap detik seperti saldo dompet, stok barang yang laris, atau status pesanan real-time, karena risiko menampilkan data basi jauh lebih besar daripada keuntungan kecepatannya. Aturan praktisnya sederhana: kalau sebuah data dibaca sepuluh kali lebih sering daripada ditulis, data itu kandidat cache yang bagus.","type":"paragraph"},{"kind":"tip","text":"Cache data yang dibaca minimal 10 kali lebih sering daripada ditulis. Data yang berubah terus-menerus justru lebih murah dibaca langsung dari database daripada di-cache lalu diinvalidasi berkali-kali.","title":"Aturan praktis 10:1","type":"callout"},{"level":2,"text":"Pola Cache-Aside","type":"heading"},{"text":"Pola yang paling umum dipakai adalah **cache-aside**, kadang disebut lazy loading. Alurnya begini: aplikasi mengecek Redis dulu setiap kali butuh data. Kalau datanya ada (**cache hit**), langsung dipakai tanpa menyentuh database sama sekali. Kalau tidak ada (**cache miss**), aplikasi membaca dari database, lalu menyimpan hasilnya ke Redis sebelum mengembalikannya ke pengguna, supaya request berikutnya langsung hit. Pola ini populer karena sederhana dan aman: database tetap menjadi sumber kebenaran, sedangkan Redis hanyalah salinan yang bisa hilang kapan saja tanpa merusak data. Kalau Redis mati atau datanya terhapus, aplikasi tetap jalan, hanya lebih lambat sementara sampai cache terisi lagi.","type":"paragraph"},{"code":"import json\nimport redis\n\nr = redis.Redis(host=\"localhost\", port=6379, decode_responses=True)\n\ndef get_product(product_id: int) -> dict:\n    key = f\"product:{product_id}\"\n    cached = r.get(key)\n    if cached:  # cache hit: 0,1-1 ms, tanpa query database\n        return json.loads(cached)\n    product = db.query(\"SELECT * FROM products WHERE id = %s\", (product_id,))\n    r.setex(key, 300, json.dumps(product))  # simpan 300 detik (TTL 5 menit)\n    return product","filename":"cache_aside.py","language":"python","type":"code"},{"text":"Perhatikan bahwa contoh di atas selalu menulis ke cache dengan **TTL (time to live)** 300 detik. Tanpa TTL, data basi bisa bertahan selamanya dan kamu tidak akan pernah tahu kapan terakhir kali data itu diperbarui. TTL adalah pengaman paling murah: kalaupun ada bug pada logika invalidasi, data yang salah akan hilang sendiri paling lambat setelah TTL habis. Untuk data yang hampir tidak pernah berubah, seperti daftar negara atau kategori, TTL 1 sampai 24 jam masih wajar. Untuk data yang berubah beberapa kali sehari, pakai TTL 60 sampai 300 detik.","type":"paragraph"},{"level":2,"text":"TTL dan Eviction","type":"heading"},{"text":"Redis menyimpan semua data di RAM, dan RAM itu terbatas. Karena itu setiap deployment Redis wajib mengatur dua hal: **maxmemory** (batas RAM yang boleh dipakai Redis) dan **maxmemory-policy** (aturan membuang data saat RAM penuh). Kebijakan yang paling aman untuk cache adalah **allkeys-lru**: saat memori penuh, Redis membuang key yang paling lama tidak dipakai. Kebijakan **volatile-lru** hanya membuang key yang punya TTL, sedangkan **noeviction** membuat Redis menolak semua perintah tulis baru saat memori penuh — ini yang paling berbahaya untuk cache, karena satu lonjakan traffic bisa membuat seluruh operasi tulis gagal dan aplikasi error.","type":"paragraph"},{"code":"# Batasi Redis ke 2 GB RAM, buang key yang paling lama tidak dipakai\nmaxmemory 2gb\nmaxmemory-policy allkeys-lru\n\n# Alternatif: hanya buang key yang punya TTL\n# maxmemory-policy volatile-lru\n\n# Cek pemakaian memori saat ini\n# redis-cli INFO memory | grep used_memory_human","filename":"redis.conf","language":"bash","type":"code"},{"kind":"warning","text":"Tanpa batas maxmemory, Redis akan terus memakai RAM sampai sistem operasi kehabisan memori dan membunuh proses lain, termasuk database. Selalu set maxmemory di bawah 75% RAM server, dan jangan pernah memakai kebijakan noeviction untuk cache.","title":"Jangan biarkan maxmemory kosong","type":"callout"},{"level":2,"text":"Invalidasi Cache","type":"heading"},{"text":"Ada pepatah terkenal di dunia engineering: hanya ada dua hal sulit dalam ilmu komputer, yaitu invalidasi cache dan penamaan sesuatu. Saat data di database berubah, salinan lamanya di Redis harus dibuang atau diperbarui, kalau tidak pengguna akan melihat data basi. Strategi paling sederhana adalah mengandalkan TTL pendek, misalnya 60 detik, sehingga data basi paling lama bertahan semenit. Strategi yang lebih presisi adalah invalidasi eksplisit: setiap kali aplikasi menulis ke database, ia juga menghapus key terkait di Redis. Strategi ketiga adalah **versioning key**, misalnya `product:42:v3`, sehingga deploy atau perubahan skema otomatis membuat key lama tidak terpakai lagi.","type":"paragraph"},{"items":["**TTL pendek (60-300 detik):** paling mudah, data basi hilang sendiri, cocok untuk data yang tidak kritis.","**Invalidasi eksplisit saat tulis:** hapus key terkait setiap kali ada update, cocok untuk data penting seperti harga dan stok.","**Versioning key:** ubah versi pada nama key saat skema berubah, semua cache lama otomatis tidak terpakai."],"ordered":false,"type":"list"},{"level":2,"text":"Redis untuk Session dan Rate Limit","type":"heading"},{"text":"Selain cache query, Redis sangat cocok untuk dua kebutuhan lain yang menuntut kecepatan dan TTL: **session** dan **rate limit**. Session yang disimpan di Redis membuat aplikasi bisa berjalan di banyak server sekaligus tanpa sticky session, karena session mana pun bisa dibaca dari server mana pun. Rate limit juga ideal di Redis karena perintah **INCR** bersifat atomik: berapapun banyaknya request bersamaan, hitungannya tidak akan pernah meleset. Pola klasiknya adalah satu key per pengguna per jendela waktu, misalnya `rate:192.168.1.10:20261113:15`, yang di-increment setiap request dan diberi TTL 60 detik.","type":"paragraph"},{"code":"# Rate limit sederhana: maksimal 100 request per menit per IP\n# INCR bersifat atomik, jadi aman untuk ribuan request bersamaan\ncount=$(redis-cli INCR \"rate:192.168.1.10:minute\")\nif [ \"$count\" -eq 1 ]; then\n  redis-cli EXPIRE \"rate:192.168.1.10:minute\" 60\nfi\nif [ \"$count\" -gt 100 ]; then\n  echo \"429 Too Many Requests\"\nfi","filename":"rate-limit.sh","language":"bash","type":"code"},{"level":2,"text":"Pipeline: Kurangi Round Trip","type":"heading"},{"text":"Satu hal yang sering dilupakan adalah **round trip**: setiap perintah Redis dari aplikasi membutuhkan satu perjalanan pulang-pergi melalui jaringan. Di dalam satu data center, satu round trip biasanya 0,1 sampai 0,5 milidetik, kecil, tetapi kalau kamu mengirim 100 perintah satu per satu, totalnya jadi 10 sampai 50 milidetik hanya untuk menunggu jaringan. **Pipeline** mengirim banyak perintah sekaligus dalam satu paket dan menerima semua jawabannya bersamaan, sehingga 100 perintah selesai hampir secepat satu perintah. Gunakan pipeline setiap kali kamu perlu membaca atau menulis banyak key sekaligus, misalnya saat mengisi cache untuk satu halaman yang butuh 20 potong data.","type":"paragraph"},{"code":"import redis\n\nr = redis.Redis(host=\"localhost\", port=6379, decode_responses=True)\n\n# Tanpa pipeline: 100 perintah = 100 round trip (~10-50 ms)\n# Dengan pipeline: 100 perintah = 1 round trip (~0,5 ms)\npipe = r.pipeline()\nfor product_id in range(1, 101):\n    pipe.get(f\"product:{product_id}\")\nresults = pipe.execute()  # semua jawaban kembali sekaligus","filename":"pipeline.py","language":"python","type":"code"},{"headers":["Operasi","Tanpa cache (database)","Dengan Redis"],"rows":[["Baca detail produk","8-40 ms","0,2-0,8 ms"],["Daftar kategori","15-60 ms","0,2-0,8 ms"],["Cek session pengguna","5-20 ms","0,1-0,5 ms"],["Hitung rate limit","10-30 ms","0,2-0,6 ms"],["Throughput satu server","~2.000 req/detik","~100.000 op/detik"]],"type":"table"},{"kind":"info","text":"Latency database sangat tergantung query, index, dan beban server. Ukur sendiri dengan redis-benchmark dan slow query log di environment kamu sebelum memutuskan angka target.","title":"Angka di atas adalah kisaran umum","type":"callout"},{"level":2,"text":"Referensi","type":"heading"},{"text":"Dokumentasi resmi dan panduan lanjutan tersedia di [Redis Documentation](https://redis.io/docs/latest/) dan [Redis Cache Patterns](https://redis.io/docs/latest/develop/use/patterns/).","type":"paragraph"}]', '2026-11-13');
